// ===== ROLES DE LA PROMOTORÍA - compatibles con legacy =====
const ROLES = {
  // Legacy
  admin: { key: 'admin', label: 'Admin', level: 90 },
  editor: { key: 'editor', label: 'Editor', level: 70 },
  maestro: { key: 'maestro', label: 'Maestro', level: 60 },
  alumno: { key: 'alumno', label: 'Alumno', level: 20 },
  // Nuevos
  gm: { key: 'gm', label: 'GM', level: 100 },
  desarrollador: { key: 'desarrollador', label: 'Desarrollador', level: 80 },
  capacitador: { key: 'capacitador', label: 'Capacitador', level: 60 },
  agencia: { key: 'agencia', label: 'Agencia', level: 55 },
  agente_agencia: { key: 'agente_agencia', label: 'Agente de Agencia', level: 25 },
  agente_desarrollo: { key: 'agente_desarrollo', label: 'Agente en Desarrollo', level: 20 },
  prospecto: { key: 'prospecto', label: 'Prospecto', level: 10 },
};
function hasRole(user, roles){ return roles.includes(((user||{}).role||'').toLowerCase()); }
function isGM(u){ return hasRole(u, ['gm']); }
function isAdmin(u){ return hasRole(u, ['admin','gm','desarrollador']); }
function isTeacher(u){ return hasRole(u, ['maestro','capacitador','agencia','admin','gm','desarrollador']); }
function isStudent(u){ return hasRole(u, ['alumno','agente_desarrollo','agente_agencia','prospecto']); }
function isAgencia(u){ return hasRole(u, ['agencia','admin','gm','desarrollador']); }
function canModifyUser(actor, target){
            if(!actor || !target) return false;
            // Cuentas GM protegidas: ni modificables por otros ni borrables.
            // Un GM solo puede editar su propia cuenta (datos personales y contraseña).
            if(isGM(target)) return isGM(actor) && String(actor.id)===String(target.id);
            return !isGM(target);
        }
// ===== FIN ROLES =====

        
/* v6.5: Optimización localStorage - debounce save */
let saveDBTimeout = null;
const originalSaveDB = window.saveDB;
window.saveDB = function() {
  if (saveDBTimeout) clearTimeout(saveDBTimeout);
  saveDBTimeout = setTimeout(()=>{
    try {
      if (typeof originalSaveDB==='function') originalSaveDB();
      // Inicializar IDB si hay grabaciones grandes
      if (!guiaIDB) initIDB().catch(()=>{});
    } catch(e) { console.warn('saveDB v6.5 error', e); }
  }, 500);
};

        function getUnreadNotifications(){
            if(!db.notifications) return 0;
            var roles = ['admin','gm','agencia','desarrollador'];
            if(roles.indexOf((currentUser.role||'').toLowerCase())===-1) return 0;
            var count=0;
            for(var i=0;i<db.notifications.length;i++){ var n=db.notifications[i]; if(!(n.readBy||[]).includes(currentUser.id)) count++; }
            return count;
        }
        function markNotificationsRead(){
            if(!db.notifications) return;
            for(var i=0;i<db.notifications.length;i++){ var n=db.notifications[i]; if(!n.readBy) n.readBy=[]; if(n.readBy.indexOf(currentUser.id)===-1) n.readBy.push(currentUser.id); }
            saveDB(); render();
        }
        window.currentRankingTab = 'mensual';
        function setRankingTab(tab){
            window.currentRankingTab = tab;
            var btns=document.querySelectorAll('[id^=tab-]');
            for(var i=0;i<btns.length;i++){ btns[i].classList.remove('bg-white','shadow-sm','font-medium'); btns[i].classList.add('text-slate-600'); }
            var active=document.getElementById('tab-'+tab);
            if(active){ active.classList.add('bg-white','shadow-sm','font-medium'); active.classList.remove('text-slate-600'); }
            renderRanking();
        }
        function renderRanking(){
            var container=document.getElementById('ranking-container');
            var podio=document.getElementById('ranking-podio');
            if(!container) return;
            var agentes=(db.users||[]).filter(function(u){ var r=(u.role||'').toLowerCase(); return r==='agente_agencia' || r==='agente_desarrollo' || r==='alumno'; });
            var ventas=db.ventas||[];
            var now=new Date();
            function inPeriod(v,tab){
                var d=new Date(v.fecha||v.ts||Date.now());
                if(tab==='mensual') return d.getMonth()===now.getMonth() && d.getFullYear()===now.getFullYear();
                if(tab==='trimestral'){ var q=Math.floor(now.getMonth()/3); var qv=Math.floor(d.getMonth()/3); return q===qv && d.getFullYear()===now.getFullYear(); }
                return d.getFullYear()===now.getFullYear();
            }
            var ranking=agentes.map(function(a){
                var vs=ventas.filter(function(v){ return (v.agente===a.id || v.agenteId===a.id) && inPeriod(v, window.currentRankingTab); });
                var total=0; for(var i=0;i<vs.length;i++) total+=Number(vs[i].prima||0);
                var prevDate=new Date(now); prevDate.setMonth(now.getMonth()-1);
                var vsPrev=ventas.filter(function(v){ var d=new Date(v.fecha||v.ts||0); return (v.agente===a.id||v.agenteId===a.id) && d.getMonth()===prevDate.getMonth() && d.getFullYear()===prevDate.getFullYear(); });
                var totalPrev=0; for(var i=0;i<vsPrev.length;i++) totalPrev+=Number(vsPrev[i].prima||0);
                var variacion=totalPrev>0?Math.round((total-totalPrev)/totalPrev*100):(total>0?100:0);
                return {id:a.id,name:a.name||a.nombre||'Agente',avatar:a.avatar||'https://i.pravatar.cc/40',total:total,count:vs.length,variacion:variacion,totalPrev:totalPrev};
            }).sort(function(a,b){ return b.total-a.total; });

            // Podio Top 3
            if(podio){
                var medals=['🥇','🥈','🥉'];
                var colors=['border-amber-400 bg-amber-50','border-slate-400 bg-slate-50','border-orange-400 bg-orange-50'];
                var htmlPodio='<div class="grid md:grid-cols-3 gap-4 mb-4">';
                for(var i=0;i<3 && i<ranking.length;i++){
                    var r=ranking[i];
                    htmlPodio+='<div class="border-2 '+colors[i]+' rounded-2xl p-4 text-center"><div class="text-3xl mb-1">'+medals[i]+'</div><img src="'+r.avatar+'" class="w-12 h-12 rounded-full mx-auto mb-2 border-2 border-white shadow"><div class="font-bold">'+r.name+'</div><div class="text-xs text-slate-500">#'+(i+1)+' en '+window.currentRankingTab+'</div><div class="text-xl font-black mt-1">$'+r.total.toLocaleString('es-MX')+'</div><div class="text-xs '+(r.variacion>=0?'text-emerald-600':'text-red-600')+'">'+(r.variacion>=0?'+':'')+r.variacion+'% vs mes ant.</div></div>';
                }
                htmlPodio+='</div>';
                podio.innerHTML=htmlPodio;
            }

            var html='<div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="text-left text-xs text-slate-500 border-b"><th class="pb-2">#</th><th class="pb-2">Agente</th><th class="pb-2 text-right">Ventas</th><th class="pb-2 text-right">Prima</th><th class="pb-2 text-right">Var.</th></tr></thead><tbody>';
            for(var i=0;i<ranking.length;i++){
                var r=ranking[i];
                html+='<tr class="border-b last:border-0"><td class="py-2.5">'+(i+1)+'</td><td class="py-2.5"><div class="flex items-center gap-2"><img src="'+r.avatar+'" class="w-6 h-6 rounded-full"><span>'+r.name+'</span></div></td><td class="py-2.5 text-right">'+r.count+'</td><td class="py-2.5 text-right font-medium">$'+r.total.toLocaleString('es-MX')+'</td><td class="py-2.5 text-right"><span class="'+(r.variacion>=0?'text-emerald-600':'text-red-600')+'">'+(r.variacion>=0?'+':'')+r.variacion+'%</span></td></tr>';
            }
            html+='</tbody></table></div>';
            container.innerHTML=html;

            var comp=document.getElementById('comparativo-container');
            if(comp){
                var totalActual=0,totalPrev=0;
                for(var i=0;i<ranking.length;i++){ totalActual+=ranking[i].total; totalPrev+=ranking[i].totalPrev; }
                var varTotal=totalPrev>0?Math.round((totalActual-totalPrev)/totalPrev*100):0;
                comp.innerHTML='<div class="flex items-center gap-4"><div>Mes actual: <b>$'+totalActual.toLocaleString('es-MX')+'</b></div><div>Mes anterior: <b>$'+totalPrev.toLocaleString('es-MX')+'</b></div><div class="'+(varTotal>=0?'text-emerald-600':'text-red-600')+' font-medium">'+(varTotal>=0?'+':'')+varTotal+'%</div></div>';
            }
        }

function saveDB() { localStorage.setItem(DB_KEY, JSON.stringify(db)); }
        function checkStorageUsage() {
            try {
                let total = 0;
                for (let key in localStorage) {
                    if (localStorage.hasOwnProperty(key)) {
                        total += localStorage[key].length;
                    }
                }
                const totalMB = (total / 1024 / 1024).toFixed(2);
                const dbSize = localStorage.getItem('pepes_v3_db') ? (localStorage.getItem('pepes_v3_db').length / 1024 / 1024).toFixed(2) : 0;
                console.log(`Almacenamiento usado: ${totalMB}MB (DB: ${dbSize}MB)`);
                return { total: totalMB, db: dbSize };
            } catch(e) { return null; }
        }
        
        // Verificar al cargar
        setTimeout(checkStorageUsage, 2000);

        function loadDB() {
            try {
            const data = localStorage.getItem(DB_KEY);
            db = data ? JSON.parse(data) : JSON.parse(JSON.stringify(defaultDB));
            } catch(e) {
                console.warn('DB corrupta, reiniciando:', e);
                localStorage.removeItem(DB_KEY);
                db = JSON.parse(JSON.stringify(defaultDB));
            }
            if (!db.settings) db.settings = JSON.parse(JSON.stringify(defaultDB.settings));
            if (!db.settings.loginSubtitle) db.settings.loginSubtitle = "Excelencia académica, diseño premium";
            if (!db.settings.loginLine1) db.settings.loginLine1 = "Plataforma educativa";
            if (!db.settings.loginLine2) db.settings.loginLine2 = "Certificada ISO 21001";
            if (!db.settings.loginLine3) db.settings.loginLine3 = "© 2026 Broker Booster";
            if (!db.settings.primaryDark) db.settings.primaryDark = "#081c30";
            if (!db.settings.accent) db.settings.accent = "#c9a86a";
            if (!db.solicitudes) db.solicitudes = [];
            // migration
            db.lessons.forEach(l => {
                if (!l.videoType) {
                    l.videoType = l.videoUrl ? 'youtube' : 'none';
                    l.videoData = null;
                }
                if (!l.flashcards) l.flashcards = [];
                l.flashcards.forEach(f => {
                    if (!f.interval) f.interval = 1;
                    if (!f.ease) f.ease = 2.5;
                    if (!f.due) f.due = new Date().toISOString();
                    if (!f.reps) f.reps = 0;
                });
                if (l.quiz) l.quiz.forEach(q => { 
                    if (!q.type) q.type = 'multiple';
                    if (!q.explanation) q.explanation = 'Revisa la lección para entender mejor este concepto.';
                });
            });
            // 1. Progreso semanal real - añadir fecha
            if (db.progress) {
                db.progress.forEach(p => { if (!p.date) p.date = new Date().toISOString(); });
            }
            // Gamificación - asegurar XP en usuarios
            if (db.users) {
                db.users.forEach(u => { 
                    if (typeof u.xp !== 'number') u.xp = 0; 
                    if (!Array.isArray(u.students)) u.students = [];
                    if (typeof u.streak !== 'number') u.streak = 0;
                    if (!u.lastStudy) u.lastStudy = null;
                });
            }
            // Gamificación - flags en progreso
            if (db.progress) {
                db.progress.forEach(p => { 
                    if (p.xpAwardedView === undefined) p.xpAwardedView = false;
                    if (p.xpAwardedQuiz === undefined) p.xpAwardedQuiz = false;
                });
            }
            // Exámenes - inicializar arrays
            if (!db.exams) db.exams = [];
            if (!db.examAttempts) db.examAttempts = [];
            if (!db.messages) db.messages = [];
            if (!db.glossaryCategories) db.glossaryCategories = [{ id: 1, name: 'General' }];
            if (!db.glossaryConcepts) db.glossaryConcepts = [];
            if (!db.liveClasses) db.liveClasses = [];
            if (!db.notifications) db.notifications = [];
            if (!db.carruselCirculares) db.carruselCirculares = {
                circulares: { titulo: 'Capacitación Semanal', dia: 'Martes', horario: '19:00', tema: 'Estrategias de Cierre', ponente: 'Equipo', invitado: '', imagen: 'https://images.unsplash.com/photo-1551836022-d5d88e9218df?q=80&w=1200', zoom: 'https://zoom.us/j/123456789', participantes: [] },
                carrusel: { titulo: 'Reunión Semanal', dia: 'Miércoles', horario: '19:00', tema: 'Productos y Argumentarios', ponente: 'Equipo', invitado: '', imagen: 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?q=80&w=1200', zoom: 'https://zoom.us/j/987654321', participantes: [] }
            };
            // Migración: asegurar cuentas GM Marín y GM Villegas en bases existentes
            if (db.users && !db.users.some(u=>u.role==='gm' && (u.username==='gmmarin'||u.name==='GM Marín'))) {
                let nid = Math.max(0,...db.users.map(u=>Number(u.id)||0))+1;
                db.users.push({ id: nid, username: 'gmmarin', role: 'gm', name: 'GM Marín', email: 'gmmarin@portal.com', avatar: 'https://i.pravatar.cc/40?u=gmmarin', xp: 0, students: [], phone: '521000000000' });
            }
            if (db.users && !db.users.some(u=>u.role==='gm' && (u.username==='gmvillegas'||u.name==='GM Villegas'))) {
                let nid = Math.max(0,...db.users.map(u=>Number(u.id)||0))+1;
                db.users.push({ id: nid, username: 'gmvillegas', role: 'gm', name: 'GM Villegas', email: 'gmvillegas@portal.com', avatar: 'https://i.pravatar.cc/40?u=gmvillegas', xp: 0, students: [], phone: '521000000000' });
            }
            // Migración: renombrar títulos antiguos (Circulares→Capacitación Semanal, Carrusel→Reunión Semanal)
            if (db.carruselCirculares) {
                if (db.carruselCirculares.circulares && (!db.carruselCirculares.circulares.titulo || /circular/i.test(db.carruselCirculares.circulares.titulo))) db.carruselCirculares.circulares.titulo = 'Capacitación Semanal';
                if (db.carruselCirculares.carrusel && (!db.carruselCirculares.carrusel.titulo || /carrusel/i.test(db.carruselCirculares.carrusel.titulo))) db.carruselCirculares.carrusel.titulo = 'Reunión Semanal';
            }
            if (!db.posts) db.posts = [];
            if (!db.groupMessages) db.groupMessages = [];
            if (!db.library) db.library = [];
            if (!Array.isArray(db.siniestros)) db.siniestros = []; // Expedientes de la sección Siniestros y Cancelaciones
            if (!Array.isArray(db.autoCartera)) db.autoCartera = []; // Cartera Automotriz (Comercial Automotriz)
            if (!db.autoHub) db.autoHub = { unidades:[], clientes:[], metas:[], ventas:[], guion:null, publicidad:[], practica:[], simConfig:null }; // Agencia Automotriz virtual
            Object.keys(db.rolePermissions||{}).forEach(function(r){ var perms=db.rolePermissions[r]; if(Array.isArray(perms)&&perms.indexOf('auto-cartera')>=0){ ['auto-unidades','auto-clientes','auto-equipo','auto-monitoreo','auto-metas','auto-simulador','auto-guion','auto-pauta','auto-practica'].forEach(function(s){ if(perms.indexOf(s)<0) perms.push(s); }); } });
            if (!Array.isArray(db.finCartera)) db.finCartera = []; // Cartera Financiera (Comercial Financiero)
            if (!Array.isArray(db.inmCartera)) db.inmCartera = []; // Cartera Inmobiliaria (Comercial Inmobiliario)
            if (!db.rolePermissions) db.rolePermissions = {
                admin: ['dashboard','leaderboard','carrusel-circulares','users','monitoreo','formacion','generations','groups','categories','lessons','tareas','biblioteca','live-classes','exams','messages','reports','glossary','personalizar','solicitudes','oferta-valor','editor','mi-equipo','convenciones','mis-clientes','siniestros','auto-cartera','fin-cartera','inm-cartera','mi-agenda', 'resultados-prospectos','centro-mensajes','guion-llamadas','casos-exito','publicidad','comparador-productos'],
                gm: ['dashboard','leaderboard','carrusel-circulares','users','monitoreo','formacion','generations','groups','categories','lessons','tareas','biblioteca','live-classes','exams','messages','reports','glossary','personalizar','solicitudes','oferta-valor','editor','control-accesos','mi-equipo','convenciones','mis-clientes','siniestros','ai-lobby','auto-cartera','fin-cartera','inm-cartera','mi-agenda', 'resultados-prospectos','centro-mensajes','guion-llamadas','casos-exito','publicidad','comparador-productos'],
                desarrollador: ['dashboard','leaderboard','carrusel-circulares','my-groups','categories','lessons','tareas','biblioteca','live-classes','exams','messages','mis-clientes','siniestros','auto-cartera','fin-cartera','inm-cartera', 'resultados-prospectos','guion-llamadas'],
                maestro: ['dashboard','leaderboard','carrusel-circulares','my-groups','categories','lessons','tareas','biblioteca','live-classes','exams','messages','mi-equipo','convenciones','monitoreo','guion-llamadas','centro-mensajes'],
                capacitador: ['dashboard','leaderboard','carrusel-circulares','my-groups','tareas','biblioteca','live-classes','exams'],
                agencia: ['dashboard','leaderboard','carrusel-circulares','my-groups','tareas','biblioteca','live-classes','exams','messages','mi-equipo','monitoreo','convenciones','mis-clientes','siniestros','auto-cartera','fin-cartera','inm-cartera','guion-llamadas','centro-mensajes'],
                editor: ['dashboard','leaderboard','carrusel-circulares','editor','oferta-valor','personalizar','casos-exito','guion-llamadas','publicidad','comparador-productos'],
                alumno: ['dashboard','leaderboard','carrusel-circulares','my-aula','my-courses','tareas','biblioteca','live-classes','my-progress','exams','messages','mis-clientes','siniestros','auto-cartera','fin-cartera','inm-cartera','guion-llamadas','casos-exito'],
                agente_desarrollo: ['dashboard','leaderboard','carrusel-circulares','my-aula','my-courses','tareas','biblioteca','live-classes','my-progress','exams','messages','mis-clientes','siniestros','auto-cartera','fin-cartera','inm-cartera','guion-llamadas','casos-exito','centro-mensajes'],
                agente_agencia: ['dashboard','leaderboard','carrusel-circulares','my-aula','my-courses','tareas','biblioteca','live-classes','my-progress','exams','messages','mis-clientes','siniestros','auto-cartera','fin-cartera','inm-cartera','guion-llamadas','casos-exito','centro-mensajes'],
                prospecto: ['mi-experiencia','oferta-valor','plan-carrera','chat-reclutador','agenda-prospectos']
            };

            // PATCH 2026-06-18: forzar permisos de monitoreo y mi-equipo para agencia/maestro
            if(db.rolePermissions){
                // Migración: secciones nuevas visibles en Control de Accesos desde el arranque
                const migracionSecciones = { admin:['centro-mensajes','guion-llamadas','casos-exito'], gm:['centro-mensajes','guion-llamadas','casos-exito'], maestro:['guion-llamadas','centro-mensajes'], agencia:['guion-llamadas','centro-mensajes'], desarrollador:['guion-llamadas'], editor:['casos-exito'], alumno:['guion-llamadas','casos-exito'], agente_desarrollo:['guion-llamadas','casos-exito','centro-mensajes'], agente_agencia:['guion-llamadas','casos-exito','centro-mensajes'] };
                // Migración: Publicidad + Comparador de Productos (auditoría 2026-09)
                const migracionF5 = { admin:['publicidad','comparador-productos'], gm:['publicidad','comparador-productos'], editor:['publicidad','comparador-productos','guion-llamadas','casos-exito'], desarrollador:['publicidad','comparador-productos'], maestro:['comparador-productos'], agencia:['comparador-productos'], capacitador:['comparador-productos'], alumno:['comparador-productos'], agente_desarrollo:['comparador-productos'], agente_agencia:['comparador-productos'] };
                Object.keys(migracionF5).forEach(r => { if(db.rolePermissions[r]){ migracionF5[r].forEach(s => { if(!db.rolePermissions[r].includes(s)) db.rolePermissions[r].push(s); }); } });
                Object.keys(migracionSecciones).forEach(r => { if(db.rolePermissions[r]){ migracionSecciones[r].forEach(s => { if(!db.rolePermissions[r].includes(s)) db.rolePermissions[r].push(s); }); } });
                if(db.rolePermissions.agencia && !db.rolePermissions.agencia.includes('monitoreo')){
                    db.rolePermissions.agencia.push('monitoreo','mi-equipo','convenciones');
                }
                if(db.rolePermissions.maestro && !db.rolePermissions.maestro.includes('monitoreo')){
                    db.rolePermissions.maestro.push('monitoreo');
                }
                // PATCH 2026-06-23: añadir mis-clientes
                const rolesConClientes = ['admin','gm','desarrollador','agencia','alumno','agente_desarrollo','agente_agencia'];
                rolesConClientes.forEach(r => {
                    if(db.rolePermissions[r] && !db.rolePermissions[r].includes('mis-clientes')){
                        db.rolePermissions[r].push('mis-clientes');
                    }
                });
                // PATCH practica-sesiones: visible para todos los roles comerciales/capacitadores
                Object.keys(db.rolePermissions||{}).forEach(r => {
                    const perms = db.rolePermissions[r];
                    if(Array.isArray(perms) && (perms.includes('mis-clientes')||perms.includes('monitoreo')) && !perms.includes('practica-sesiones')){
                        perms.push('practica-sesiones');
                    }
                });
                // PATCH simulador: todo rol comercial con mis-clientes/monitoreo ve el Simulador de ingresos
                Object.keys(db.rolePermissions||{}).forEach(r => {
                    const perms = db.rolePermissions[r];
                    if(Array.isArray(perms) && (perms.includes('mis-clientes')||perms.includes('monitoreo')) && !perms.includes('simulador')){
                        perms.push('simulador');
                    }
                });
                // PATCH live-classes: restaurar "Clases En Vivo" (la sección existe pero faltaba el permiso guardado en BDs viejas)
                ['admin','gm','desarrollador','maestro','capacitador','agencia','alumno','agente_desarrollo','agente_agencia'].forEach(r => {
                    const perms = (db.rolePermissions||{})[r];
                    if(Array.isArray(perms) && !perms.includes('live-classes')) perms.push('live-classes');
                });
                // PATCH mis-metas: todo rol comercial con mis-clientes/monitoreo puede ver Mis Metas (gráficas individuales)
                Object.keys(db.rolePermissions||{}).forEach(r => {
                    const perms = db.rolePermissions[r];
                    if(Array.isArray(perms) && (perms.includes('mis-clientes')||perms.includes('monitoreo')) && !perms.includes('mis-metas')){
                        perms.push('mis-metas');
                    }
                });
                // PATCH siniestros: nueva sección "Procesos, Siniestros y Cancelaciones" (auditoría 2026-09-25).
                // Ligada a Mis Clientes: todo rol que vea clientes/monitoreo puede dar seguimiento a siniestros y cancelaciones.
                Object.keys(db.rolePermissions).forEach(r => {
                    const perms = db.rolePermissions[r];
                    if(Array.isArray(perms) && (perms.includes('mis-clientes')||perms.includes('monitoreo')) && !perms.includes('siniestros')){
                        perms.push('siniestros');
                    }
                });
                // PATCH cotizaciones: nueva sección "Cotizaciones y Emisiones" (2026-10).
                // Solicitan: agente_agencia y agente_desarrollo (y procesadores). Procesan: agencia/admin/gm/desarrollador.
                const migracionCot = { admin:['cotizaciones'], gm:['cotizaciones'], desarrollador:['cotizaciones'], agencia:['cotizaciones'], agente_desarrollo:['cotizaciones'], agente_agencia:['cotizaciones'] };
                Object.keys(migracionCot).forEach(r => { if(db.rolePermissions[r] && Array.isArray(db.rolePermissions[r]) && !db.rolePermissions[r].includes('cotizaciones')) db.rolePermissions[r].push('cotizaciones'); });
                // PATCH verticales comerciales: Cartera Automotriz / Financiera / Inmobiliaria para roles con mis-clientes
                Object.keys(db.rolePermissions).forEach(r => {
                    const perms = db.rolePermissions[r];
                    if(Array.isArray(perms) && perms.includes('mis-clientes') && !perms.includes('auto-cartera')){
                        perms.push('auto-cartera','fin-cartera','inm-cartera');
                    }
                });
            }

            if (!db.tasks) db.tasks = [];
            if (!db.taskSubmissions) db.taskSubmissions = [];
            if (!db.planes) db.planes = [];
            if (db.categories) { db.categories.forEach(c => { if (!c.hasOwnProperty('planId')) c.planId = null; }); }
            if (db.users) { db.users.forEach(u => { if (!u.phone) u.phone = '521000000000'; }); }
            if (db.categories) { db.categories.forEach(c => { if (!c.image) c.image = ''; }); }
            if (db.generations) { db.generations.forEach(g => { if (!g.image) g.image = ''; }); }
            if (db.groups) { db.groups.forEach(g => { if (!g.image) g.image = ''; }); }
            // FASE 2 - seed datos de prueba
            if (!db.generations.length) {
                db.generations.push({ id: 1, name: 'Generación 2025', startDate: '2025-01-01', endDate: '2025-12-31' });
            }
            if (!db.groups.length) {
                db.groups.push({ id: 1, generationId: 1, name: 'Grupo A', tutorId: 2, schedule: 'Lun-Mié 18:00' });
            }
            if (!db.enrollments.some(e=>e.userId===3)) {
                db.enrollments.push({ id: 1, userId: 3, generationId: 1, groupId: 1, enrolledAt: new Date().toISOString() });
            }
            if (!db.posts.some(p=>p.groupId===1)) {
                if(!db.posts.some(p=>p.id)) db.posts.forEach(p=>{if(p.isBestAnswer===undefined) p.isBestAnswer=false;}); db.posts.push(
                    { id: Date.now()-20000, groupId: 1, authorId: 2, content: '¡Bienvenidos a la nueva generación! Recuerden revisar el material de Álgebra.', pinned: true, createdAt: new Date(Date.now()-86400000*2).toISOString() },
                    { id: Date.now()-10000, groupId: 1, authorId: 2, content: 'Recordatorio: clase en vivo mañana a las 18:00.', pinned: false, createdAt: new Date(Date.now()-86400000).toISOString() }
                );
            }
            if (!db.groupMessages.some(m=>m.groupId===1)) {
                db.groupMessages.push(
                    { id: 1, groupId: 1, authorId: 3, content: 'Hola profe, ¿dónde encuentro la tarea?', createdAt: new Date(Date.now()-3600000*5).toISOString() },
                    { id: 2, groupId: 1, authorId: 2, content: 'Hola Ana, está en Mis Cursos > Matemáticas', createdAt: new Date(Date.now()-3600000*4).toISOString() },
                    { id: 3, groupId: 1, authorId: 3, content: '¡Perfecto, gracias!', createdAt: new Date(Date.now()-3600000*3).toISOString() }
                );
            }
            saveDB();
        }

