        function showCampusLogin() {
            document.getElementById('public-portal').classList.add('hidden');
            document.getElementById('login-screen').classList.remove('hidden');
            document.getElementById('login-screen').classList.add('flex');
            sessionStorage.setItem('login_destination', 'campus');
            document.querySelector('#login-screen h2').textContent = 'Iniciar Sesión';
        }

        function showAdminLogin() {
            document.getElementById('public-portal').classList.add('hidden');
            document.getElementById('login-screen').classList.remove('hidden');
            document.getElementById('login-screen').classList.add('flex');
            sessionStorage.setItem('login_destination', 'admin');
            document.querySelector('#login-screen h2').textContent = 'Acceso Administrativo';
        }

        function login(username, password) {
            const user = db.users.find(u => u.username === username && u.password === password);
            if (user) {
                const destination = sessionStorage.getItem('login_destination') || 'campus';
                sessionStorage.removeItem('login_destination');

                if (destination === 'admin') {
                    if (isAdmin(user) || isAdmin(user)) {
                        currentUser = user;
                        sessionStorage.setItem('pepes_user', JSON.stringify(user));
                        document.getElementById('login-screen').classList.add('hidden');
                        document.getElementById('public-portal').classList.add('hidden');
                        document.getElementById('main-app').classList.remove('hidden');
                        initializeApp();
                        setTimeout(() => navigateTo((user.role||'').toLowerCase()==='gm' ? 'dashboard' : 'editor'), 100);
                        return true;
                    } else {
                        alert('Acceso denegado. Solo administradores y editores.');
                        return false;
                    }
                } else {
                    if (isAdmin(user)) {
                        alert('Los editores solo pueden acceder al panel de edición. Usa "Acceso administrativo".');
                        return false;
                    }
                    currentUser = user;
                    sessionStorage.setItem('pepes_user', JSON.stringify(user));
                    document.getElementById('login-screen').classList.add('hidden');
                    document.getElementById('public-portal').classList.add('hidden');
                    document.getElementById('main-app').classList.remove('hidden');
                    initializeApp();
                    return true;
                }
            }
            return false;
        }
        function logout() {
            currentUser = null;
            try{ guiaUnmount(); }catch(e){}
            sessionStorage.removeItem('pepes_user');
            document.getElementById('main-app').classList.add('hidden');
            document.getElementById('login-screen').classList.add('hidden');
            document.getElementById('public-portal').classList.remove('hidden');
            document.getElementById('login-form').reset();
            renderPublicPortal();
        }

