function renderCaminosCards(){
  const cards=(db.settings.caminos && Array.isArray(db.settings.caminos.cards) && db.settings.caminos.cards.length)?db.settings.caminos.cards:caminosDefaults();
  return cards.map(c=>{
    const destacado=!!c.destacado;
    const cardCls = destacado ? 'bg-slate-950 text-white p-8 rounded-3xl border-2 border-slate-950 shadow-2xl scale-105' : 'bg-slate-50/50 p-8 rounded-3xl border-2 border-slate-200 hover:border-emerald-600 hover:shadow-2xl hover:shadow-emerald-600/10 transition-all';
    const descCls = destacado ? 'text-slate-300' : 'text-slate-600';
    const btnCls = destacado ? 'bg-emerald-600 text-white rounded-xl hover:bg-emerald-700 transition shadow-lg' : 'border-2 border-slate-900 rounded-xl hover:bg-slate-900 hover:text-white transition';
    const badge = destacado ? '<div class="absolute -top-4 left-1/2 -translate-x-1/2 px-4 py-1 bg-emerald-600 text-white text-xs font-bold rounded-full">MÁS POPULAR</div>' : '';
    const items=(c.items||[]).map(it=>'<li class="flex items-start gap-2"><i class="fas fa-check text-emerald-500 mt-0.5"></i><span>'+psEscape(it)+'</span></li>').join('');
    return '<div class="group relative '+cardCls+'">'+badge+
      '<h3 class="text-2xl font-bold mb-3">'+psEscape(c.titulo)+'</h3>'+
      '<p class="'+descCls+' mb-6">'+psEscape(c.desc)+'</p>'+
      '<ul class="space-y-2.5 mb-8 text-sm">'+items+'</ul>'+
      '<button onclick="openSolicitudModal(\''+(((db.settings.caminos||{}).ctas)&&(db.settings.caminos.ctas[c.origen||'cero'])?c.origen:(c.origen||'cero'))+'\')" class="w-full py-3 font-semibold '+btnCls+'">'+psEscape(c.cta)+'</button>'+
      '</div>';
  }).join('');
}
