function solicitudesSinVer(){
    try{
        const hasta = currentUser && currentUser.solicitudesVistasHasta ? new Date(currentUser.solicitudesVistasHasta) : null;
        return (db.solicitudes||[]).filter(s => s.estado === 'nuevo' && (!hasta || new Date(s.fecha) > hasta)).length;
    }catch(e){ return 0; }
}
function updateBadgeSolicitudes(n){
    try{
        const badge = document.getElementById('badge-solicitudes');
        if(badge){
            if(n > 0){ badge.textContent = n > 9 ? '9+' : String(n); badge.classList.remove('hidden'); }
            else { badge.classList.add('hidden'); badge.textContent = '0'; }
        }
    }catch(e){}
    try{
        const hb = document.getElementById('badge-solicitudes-header');
        if(hb){
            if(n > 0){ hb.textContent = n > 9 ? '9+' : String(n); hb.classList.remove('hidden'); }
            else { hb.classList.add('hidden'); hb.textContent = '0'; }
        }
        const bell = document.getElementById('bell-solicitudes');
        if(bell){
            const _rol = ((currentUser && currentUser.role) || '').toLowerCase();
            bell.classList.toggle('hidden', !(_rol === 'admin' || _rol === 'gm'));
        }
    }catch(e){}
}
function marcarSolicitudesVistas(){
    try{
        if(!currentUser) return;
        currentUser.solicitudesVistasHasta = new Date().toISOString();
        const udb = (db.users||[]).find(u => u.id === currentUser.id);
        if(udb) udb.solicitudesVistasHasta = currentUser.solicitudesVistasHasta;
        saveDB();
        updateBadgeSolicitudes(0);
        window.lastSolicitudesCount = (db.solicitudes||[]).length;
    }catch(e){}
}
function checkNuevasSolicitudes(){
    try{
        const rol = (currentUser && currentUser.role) || '';
        if(rol !== 'gm' && rol !== 'admin') return;
        updateBadgeSolicitudes(solicitudesSinVer());
        const actuales = (db.solicitudes||[]).length;
        if(typeof window.lastSolicitudesCount === 'undefined') window.lastSolicitudesCount = actuales;
        if(actuales > window.lastSolicitudesCount){
            const nuevos = actuales - window.lastSolicitudesCount;
            if(window.showToast) showToast(`🔔 ${nuevos} nueva solicitud`, 'info');
            try{ new Audio('https://actions.google.com/sounds/v1/alarms/beep_short.ogg').play().catch(()=>{}); }catch(e){}
            if(window.Notification && Notification.permission==='granted'){ try{ new Notification('Nueva solicitud', {body: `${nuevos} candidato(s) nuevo(s)`}); }catch(e){} }
            window.lastSolicitudesCount = actuales;
        }
    }catch(e){}
}
