/* Saludo de entrada: repertorio local instantáneo; la IA añade un saludo propio cuando hay API */
async function psSaludoEntrante(){
  const s = window.psSesionActiva; if(!s) return;
  const saludoLocal = psSaludoLocal(s);
  s.mensajes.push({rol:'prospecto', texto:saludoLocal, ts:Date.now()});
  psRenderChatDom();
  psSpeak(saludoLocal);
  if(window.psAPIKey){
    try{
      const saludoIA = await psPedirIA('__INICIO__');
      if(window.psSesionActiva && window.psSesionActiva.id===s.id && s.mensajes.length<=1){
        s.mensajes.push({rol:'prospecto', texto:saludoIA, ts:Date.now()});
        psRenderChatDom(); psSpeak(saludoIA);
      }
    }catch(e){}
  }
}
function psAbortar(){
  if(!window.confirm('¿Descartar esta sesión sin guardar?')) return;
  if(window.psSesionActiva && window.psSesionActiva.timerInt){ clearInterval(window.psSesionActiva.timerInt); }
  if(window.psMicOn){ psMicStop(); }
  psStopSpeak(); window.psSesionActiva=null; renderPracticaSesionesForce();
}
function psScrollChat(){ const c=document.getElementById('ps-chat'); if(c) c.scrollTop=c.scrollHeight; }
function psTickTimer(){
  const el=document.getElementById('ps-timer'); if(!el) return;
  const s=window.psSesionActiva; if(!s) return;
  const seg=Math.floor((Date.now()-(s.timerStart||s.inicio))/1000);
  el.textContent='⏱ '+String(Math.floor(seg/60)).padStart(2,'0')+':'+String(seg%60).padStart(2,'0');
}
function psRenderChatDom(){
  const col=document.getElementById('ps-chat-col'); if(!col) return;
  col.innerHTML=psRenderChat(); psScrollChat();
  const inp=document.getElementById('ps-input');
  if(inp){ inp.onkeydown=e=>{ if(e.key==='Enter'&&!e.shiftKey){ e.preventDefault(); psSend(); } }; setTimeout(()=>inp.focus(),50); }
  const s=window.psSesionActiva;
  if(s && !s.timerInt){ s.timerInt=setInterval(psTickTimer,1000); }
  psTickTimer();
  psMicUpdateBtn();
}
function psSend(){ const inp=document.getElementById('ps-input'); const t=(inp.value||'').trim(); if(t) psEnviarMensaje(t); }
async function psEnviarMensaje(texto){
  const s=window.psSesionActiva; if(!s||s.esperando) return;
  const inp=document.getElementById('ps-input'); if(inp) inp.value='';
  if(window.psMicFinal){ window.psMicFinal=''; }
  if(window.psMicOn && !s.micUsado){ s.micUsado=true; }
  s.mensajes.push({rol:'asesor', texto, ts:Date.now()});
  s.esperando=true;
  psRenderChatDom();
  const thinking=document.createElement('div');
  thinking.id='ps-thinking'; thinking.className='flex justify-start';
  thinking.innerHTML='<div class="bg-white border border-slate-200 rounded-2xl px-4 py-2.5 text-sm text-slate-400">escribiendo…</div>';
  const chat=document.getElementById('ps-chat'); if(chat) chat.appendChild(thinking);
  psScrollChat();
  const resp = await psMotorProspecto(texto);
  const delay = window.psAPIKey ? 100 : 500+Math.random()*700;
  await new Promise(r=>setTimeout(r, delay));
  const th=document.getElementById('ps-thinking'); if(th) th.remove();
  // detectar objeción (heurística local para stats)
  const lower=(texto||'').toLowerCase();
  const respLower=resp.toLowerCase();
  if(/(no|caro|barato|pensarlo|después|luego|banco|riesgo|perder|esposa|consultarlo|whatsapp|mándame|mandame|escéptico)/.test(respLower) && s.dificultad!=='facil'){ s.objeciones=s.objeciones||[]; s.objeciones.push({ts:Date.now()}); }
  s.mensajes.push({rol:'prospecto', texto:resp, ts:Date.now()});
  s.esperando=false;
  psRenderChatDom();
  psSpeak(resp);
}
async function psFinalizar(){
  const s=window.psSesionActiva; if(!s) return;
  if(s.mensajes.filter(m=>m.rol==='asesor').length===0){ showToast('Escribe al menos un mensaje antes de finalizar','warning'); return; }
  if(window.psMicOn){ psMicStop(); }
  if(s.timerInt){ clearInterval(s.timerInt); s.timerInt=null; }
  s.duracionMin = Math.max(1, Math.round((Date.now()-s.inicio)/60000));
  psStopSpeak();
  let fb=null;
  if(window.psAPIKey){ showToast('Analizando con IA…','info'); fb=await psAnalizarIA(); }
  if(!fb) fb=psAnalizarLocal();
  if(!fb){ showToast('No se pudo analizar la sesión','warning'); return; }
  s.feedback=fb; s.fin=Date.now();
  const d=psGetDB(); d.practicaSesiones.push(JSON.parse(JSON.stringify(s))); psSaveDB(d);
  window.psSesionActiva=null;
  const modal=document.createElement('div');
  modal.id='ps-modal-fb';
  modal.innerHTML=`<div class="fixed inset-0 z-[70]"><div class="absolute inset-0 bg-black/60 backdrop-blur-sm" onclick="psCerrarModalFb()"></div>
  <div class="relative z-10 min-h-screen flex items-center justify-center p-4"><div class="w-full max-w-2xl bg-white rounded-2xl shadow-2xl max-h-[90vh] overflow-hidden flex flex-col">
    <div class="px-6 py-4 border-b border-slate-200 flex items-center justify-between"><h3 class="font-bold text-lg text-slate-900">🎓 Retroalimentación de la sesión</h3><button onclick="psCerrarModalFb()" class="p-1.5 rounded-lg hover:bg-slate-100 text-slate-400">✕</button></div>
    <div class="p-6 overflow-y-auto space-y-4">${psRenderFeedback(fb,{...s, duracionMin:s.duracionMin})}</div>
    <div class="px-6 py-4 border-t border-slate-200 flex justify-end gap-2"><button onclick="psCerrarModalFb()" class="px-5 py-2.5 rounded-xl bg-indigo-600 text-white font-semibold hover:bg-indigo-700">Entendido</button></div>
  </div></div></div>`;
  document.body.appendChild(modal);
  window.psPracticaTab='historial';
}
