        const COT_PARES = ['nombre','edad','cp','suma','gama','tabulador','deducible','coaseguro','perfil','estrategia','plazo','monto','aportacion','procedencia','vehiculo','uso','curp','zona','tipo','genero','fumador','fecha_nac','app','preexistencias','comp_antiguedad','antiguedad','ocupacion','capacidad','tipo_carga','coberturas'];
        const COT_COMPANIAS_DEFECTO = ['Sin preferencia','GNP','AXA','MetLife','Chubb','HDI','Qualitas','Mapfre','Plan Seguro','BX+','Zurich','Inbursa','Banorte','Sura','ANA Seguros','Afirme','Otra'];
        function cotCfg(){
            try{ if(!db.settings || typeof db.settings!=='object') db.settings={}; if(!db.settings.cotizador) db.settings.cotizador={companias:null, checkExtra:null}; }catch(e){ return {companias:null, checkExtra:null}; }
            return db.settings.cotizador;
        }
        function cotCompanias(){ const c=cotCfg().companias; return (Array.isArray(c)&&c.length)?c:COT_COMPANIAS_DEFECTO.slice(); }
        function cotCheckExtra(ramo){
            const ov = cotCfg().checkExtra;
            if(ov && Array.isArray(ov[ramo]) && ov[ramo].length) return ov[ramo]; // lista del GM es autoritativa
            return COT_CHECK_EXTRA[ramo]||[];
        }
        function cotPuedeConfigurar(){ return hasRole(currentUser, ['gm','admin','desarrollador']); }
        const COT_PESO = { alta:25, media:12, baja:5 };
        function cotDB(){ if(!Array.isArray(db.cotizaciones)) { db.cotizaciones = []; saveDB(); } return db.cotizaciones; }
        function cotEsSolicitante(){ return hasRole(currentUser, ['agente_agencia','agente_desarrollo']); }
        function cotEsProcesador(){ return hasRole(currentUser, ['agencia','admin','gm','desarrollador']); }
        function cotUsuario(id){ const u=(db.users||[]).find(x=>String(x.id)===String(id)); return u ? u.name : 'Usuario'; }
        function cotFolioN(){ const y=new Date().getFullYear(); const n=cotDB().length+1; return 'COT-'+y+'-'+String(n).padStart(4,'0'); }
        function cotRamo(id){ return COT_RAMOS.find(r=>r.id===id) || {nombre:id, sla:48, icon:'fa-file-signature', colectivo:false, edad:[18,85]}; }
        function cotSlaInfo(s){
            const r = cotRamo(s.ramo); const sla = r.sla || 48;
            const ini = new Date(s.creado).getTime();
            let fin = Date.now();
            if((s.estado==='cotizada'||s.estado==='emitida') && s.cotizacion && s.cotizacion.enviadaEn) fin = new Date(s.cotizacion.enviadaEn).getTime();
            if(s.estado==='rechazada'||s.estado==='cancelada') fin = new Date(s.estadoDesde).getTime();
            const horas = Math.max(0,(fin-ini)/3600000);
            const pct = Math.min(150, Math.round(horas/sla*100));
            const cerrado = ['cotizada','emitida','rechazada','cancelada'].includes(s.estado);
            const nivel = cerrado ? (horas<=sla?'ok':'over') : (pct>=100?'over':(pct>=75?'warn':'ok'));
            return { sla, horas, pct, nivel, activo:!cerrado };
        }
        function cotBarraSla(s){
            const i = cotSlaInfo(s);
            const color = i.nivel==='over' ? 'bg-red-500' : (i.nivel==='warn' ? 'bg-amber-500' : 'bg-emerald-500');
            const txt = i.nivel==='over' ? 'text-red-600' : (i.nivel==='warn' ? 'text-amber-600' : 'text-emerald-600');
            return '<div class="flex items-center gap-2 min-w-[130px]">'
                + '<div class="flex-1 h-1.5 bg-slate-200 rounded-full overflow-hidden"><div class="h-full rounded-full '+color+'" style="width:'+Math.min(100,i.pct)+'%"></div></div>'
                + '<span class="text-[10px] font-bold '+txt+' whitespace-nowrap">'+(i.horas>=24?Math.round(i.horas/24)+'d':Math.round(i.horas)+'h')+' / '+i.sla+'h</span></div>';
        }
        function cotMarcarVisto(s){ if(!s.vistoPor) s.vistoPor={}; s.vistoPor[currentUser.id]=Date.now(); }
        function cotNovedadesParaMi(){
            // Novedades sin ver: para solicitante, estados cotizada/aclaracion no vistos o chat nuevo; para procesador, solicitudes sin tomar o chat nuevo
            return cotDB().filter(s=>{
                if(!cotEsProcesador() && String(s.creadoPor.id)!==String(currentUser.id)) return false;
                const visto = s.vistoPor && s.vistoPor[currentUser.id] ? s.vistoPor[currentUser.id] : 0;
                const chatNuevo = (s.chat||[]).some(m => m.fecha > visto && String(m.de.id)!==String(currentUser.id));
                const estNuevo = cotEsProcesador() ? (s.estado==='solicitud') : ((s.estado==='cotizada'||s.estado==='aclaracion') && new Date(s.estadoDesde||s.creado).getTime() > visto);
                return estNuevo || chatNuevo;
            }).length;
        }
        /* ---------- Notificaciones de nuevos trámites (cotizaciones + siniestros/cancelaciones) ---------- */
        function tramiteRoles(){
            const r = ((currentUser||{}).role||'').toLowerCase();
            return ['gm','admin','desarrollador','agencia'].includes(r);
        }
        function tramiteVisto(mod){
            try{ const k = mod==='sin' ? 'tramitesSinVistosHasta' : 'tramitesCotVistosHasta'; return (currentUser||{})[k] ? new Date(currentUser[k]).getTime() : 0; }catch(e){ return 0; }
        }
        function tramitesNuevos(){
            try{
                if(!currentUser || !tramiteRoles()) return 0;
                const vc = tramiteVisto('cot');
                const vs = tramiteVisto('sin');
                const cot = cotDB().filter(s => new Date(s.creado).getTime() > vc && String(s.creadoPor.id)!==String(currentUser.id)).length;
                const sin = sinDB().filter(s => new Date(s.fechaReporte||s.fechaActualizacion||0).getTime() > vs).length;
                return cot + sin;
            }catch(e){ return 0; }
        }
        function updateBadgeTramites(){
            try{
                const b = document.getElementById('badge-tramites');
                if(!b) return;
                const n = tramitesNuevos();
                if(n>0){ b.textContent = n>9?'9+':String(n); b.classList.remove('hidden'); }
                else { b.classList.add('hidden'); b.textContent='0'; }
            }catch(e){}
        }
        function marcarTramitesVistos(mod){
            try{
                if(!currentUser) return;
                if(!mod || mod==='cot') currentUser.tramitesCotVistosHasta = new Date().toISOString();
                if(!mod || mod==='sin') currentUser.tramitesSinVistosHasta = new Date().toISOString();
                const udb = (db.users||[]).find(u => String(u.id)===String(currentUser.id));
                if(udb){ if(!mod || mod==='cot') udb.tramitesCotVistosHasta = currentUser.tramitesCotVistosHasta; if(!mod || mod==='sin') udb.tramitesSinVistosHasta = currentUser.tramitesSinVistosHasta; }
                saveDB();
            }catch(e){}
            updateBadgeTramites();
        }
        function notificarNuevoTramite(tipo, detalle){
            try{
                if(!Array.isArray(db.notifications)) db.notifications = [];
                const r = ((currentUser||{}).role||'').toLowerCase();
                if(!['gm','admin','desarrollador','agencia'].includes(r)){
                    db.notifications.unshift({ id:'tram-'+tipo+'-'+Date.now(), type:'tramite', userId:currentUser.id, msg:detalle, ts:new Date().toISOString(), readBy:[] });
                }
                db.notifications.unshift({ id:'tram-'+tipo+'-'+Date.now()+'-mgmt', type:'tramite', msg:detalle, ts:new Date().toISOString(), readBy:[] });
                if(db.notifications.length>300) db.notifications.length = 300;
            }catch(e){}
        }
        function notificarEstadoCotizacion(s, etiqueta){
            try{ if(Array.isArray(db.notifications)) db.notifications.unshift({ id:'tram-cotest-'+Date.now(), type:'tramite', msg:etiqueta+' · cotización '+s.id+' ('+(s.ramoNombre||'')+'): '+s.cliente.nombre, ts:new Date().toISOString(), readBy:[] }); }catch(e){}
        }
        function updateBadgeCotizaciones(){
            try{
                const b = document.getElementById('badge-cotizaciones');
                if(!b) return;
                const n = cotNovedadesParaMi();
                if(n>0){ b.textContent = n>9?'9+':String(n); b.classList.remove('hidden'); }
                else { b.classList.add('hidden'); b.textContent='0'; }
            }catch(e){}
        }
        function cotSnap(){
            try{ return JSON.stringify(cotDB().map(s=>({id:s.id, e:s.estado, c:(s.chat||[]).length, q:s.cotizacion?1:0}))); }catch(e){ return ''; }
        }
        function initCotizacionesPoll(){
            if(window.cotPollOn) return; window.cotPollOn = true;
            window.cotSnapPrev = cotSnap();
            setInterval(function(){
                try{
                    if(!currentUser) return;
                    updateBadgeCotizaciones();
                    const snap = cotSnap();
                    if(snap !== window.cotSnapPrev){
                        const antes = window.cotSnapPrev ? JSON.parse(window.cotSnapPrev) : [];
                        const ahora = JSON.parse(snap);
                        ahora.forEach(a=>{
                            const b = antes.find(x=>x.id===a.id); if(!b) return;
                            const s = cotDB().find(x=>x.id===a.id); if(!s) return;
                            if(String(s.creadoPor.id)===String(currentUser.id) && cotEsSolicitante()){
                                if(a.e!==b.e && ['cotizada','aclaracion','emitida','rechazada'].includes(a.e)) showToast('Cotización '+s.id+': '+(COT_ESTADO_LABEL[a.e]||a.e), a.e==='cotizada'?'success':'info');
                                else if(a.c>b.c && (s.chat||[]).length && String(s.chat[s.chat.length-1].de.id)!==String(currentUser.id)) showToast('Nuevo mensaje en '+s.id, 'info');
                            }
                        });
                        if(cotEsProcesador() && ahora.length>antes.length){ const nuevos=ahora.filter(a=>!antes.find(x=>x.id===a.id)); if(nuevos.some(a=>{const s=cotDB().find(x=>x.id===a.id); return s && String(s.creadoPor.id)!==String(currentUser.id);})) showToast('Nueva solicitud de cotización recibida', 'info'); }
                        window.cotSnapPrev = snap;
                        updateBadgeTramites();
                        if(window.lastPage==='cotizaciones' && !window.cotModalId) render();
                    }
                }catch(e){}
            }, 12000);
        }
        /* ---------- Vista principal ---------- */
        function cotListaVisible(){
            return cotDB().filter(s => cotEsProcesador() || String(s.creadoPor.id)===String(currentUser.id))
                          .sort((a,b)=> new Date(b.creado)-new Date(a.creado));
        }
        function cotKpis(lista){
            const activas = lista.filter(s=>['solicitud','revision','aclaracion'].includes(s.estado));
            const retrasadas = activas.filter(s=>cotSlaInfo(s).nivel==='over');
            const porVencer = activas.filter(s=>cotSlaInfo(s).nivel==='warn');
            const resueltas = lista.filter(s=>(s.estado==='cotizada'||s.estado==='emitida') && s.cotizacion && s.cotizacion.enviadaEn);
            const prom = resueltas.length ? (resueltas.reduce((a,s)=>a+(new Date(s.cotizacion.enviadaEn)-new Date(s.creado))/3600000,0)/resueltas.length) : 0;
            return { activas:activas.length, retrasadas:retrasadas.length, porVencer:porVencer.length, prom, total:lista.length, cotizadas:lista.filter(s=>s.estado==='cotizada').length, emitidas:lista.filter(s=>s.estado==='emitida').length };
        }
        function renderCotizaciones(){
            const lista = cotListaVisible();
            const k = cotKpis(lista);
            const filtros = ['todas','solicitud','revision','aclaracion','cotizada','emitida','rechazada','cancelada'];
            const f = window.cotFiltro || 'todas';
            const q = (window.cotBusca || '').toLowerCase();
            const filtradas = lista.filter(s => (f==='todas'||s.estado===f) && (!q || (s.id+' '+s.cliente.nombre+' '+s.ramoNombre+' '+s.compania).toLowerCase().includes(q)));
            const kpiCard = (icon,val,label,cls) => '<div class="bg-white rounded-xl border border-slate-200 p-3 flex items-center gap-3"><div class="w-9 h-9 rounded-lg '+cls+' flex items-center justify-center"><i class="fas '+icon+' text-white text-sm"></i></div><div><p class="text-xl font-bold text-slate-800 leading-none">'+val+'</p><p class="text-[11px] text-slate-500 mt-0.5">'+label+'</p></div></div>';
            return `<div class="max-w-7xl mx-auto p-4 sm:p-6">
                <div class="flex items-center justify-between flex-wrap gap-3 mb-5">
                    <div>
                        <h2 class="text-2xl font-bold text-slate-800 flex items-center gap-2"><i class="fas fa-file-signature text-emerald-600"></i> Cotizaciones y Emisiones</h2>
                        <p class="text-slate-500 text-sm mt-1">${cotEsProcesador() ? 'Bandeja de procesamiento: toma solicitudes, cotiza, analiza y envía.' : 'Solicita cotizaciones y emisiones; sigue el avance y responde aclaraciones.'}</p>
                    </div>
                    <div class="flex gap-2">
                        ${cotEsProcesador() ? `<button onclick="cotTabAnalitica()" class="px-4 py-2.5 rounded-xl bg-slate-100 text-slate-700 text-sm font-semibold hover:bg-slate-200"><i class="fas fa-chart-bar mr-1"></i> Analítica</button>` : ''}
                        ${cotPuedeConfigurar() ? `<button onclick="cotConfigModal()" class="px-4 py-2.5 rounded-xl bg-slate-100 text-slate-700 text-sm font-semibold hover:bg-slate-200"><i class="fas fa-sliders mr-1"></i> Configurar</button>` : ''}
                        <button onclick="cotModalNueva()" class="px-4 py-2.5 rounded-xl bg-emerald-600 text-white text-sm font-semibold hover:bg-emerald-700 shadow"><i class="fas fa-plus mr-1"></i> Nueva solicitud</button>
                    </div>
                </div>
                <div class="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">
                    ${kpiCard('fa-inbox', k.activas, 'Activas', 'bg-blue-500')}
                    ${kpiCard('fa-stopwatch', k.retrasadas, 'Retrasadas (SLA)', k.retrasadas?'bg-red-500':'bg-emerald-500')}
                    ${kpiCard('fa-hourglass-half', k.porVencer, 'Por vencer SLA', 'bg-amber-500')}
                    ${kpiCard('fa-paper-plane', k.prom?k.prom.toFixed(1)+'h':'—', 'Respuesta promedio', 'bg-violet-500')}
                </div>
                <div class="flex flex-wrap items-center gap-2 mb-4">
                    ${filtros.map(x=>`<button onclick="cotSetFiltro('${x}')" class="px-3 py-1.5 rounded-full text-xs font-semibold border ${f===x?'bg-slate-900 text-white border-slate-900':'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}">${x==='todas'?'Todas':(COT_ESTADO_LABEL[x]||x)}${x!=='todas'?' ('+lista.filter(s=>s.estado===x).length+')':''}</button>`).join('')}
                    <div class="ml-auto relative"><i class="fas fa-search absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>
                    <input id="cot-busca" value="${escapeHTML(q)}" oninput="cotSetBusca(this.value)" placeholder="Buscar folio, cliente, ramo…" class="pl-8 pr-3 py-2 text-sm border border-slate-200 rounded-xl w-56 focus:outline-none focus:ring-2 focus:ring-emerald-500"></div>
                </div>
                <div class="space-y-3">
                    ${filtradas.length ? filtradas.map(s=>cotFila(s)).join('') : '<div class="bg-white rounded-2xl border border-slate-200 p-10 text-center"><i class="fas fa-inbox text-4xl text-slate-300 mb-3"></i><p class="text-slate-500">No hay solicitudes aquí. Crea una con el botón «Nueva solicitud».</p></div>'}
                </div>
            </div>`;
        }
        function cotFila(s){
            const r = cotRamo(s.ramo);
            const pend = (s.checklist||[]).filter(c=>!c.ok).length;
            const chatNoLeido = (s.chat||[]).some(m=>{ const v=(s.vistoPor||{})[currentUser.id]||0; return m.fecha>v && String(m.de.id)!==String(currentUser.id); });
            return `<div class="bg-white rounded-2xl border border-slate-200 p-4 hover:shadow-md transition cursor-pointer" onclick="cotAbrir('${s.id}')">
                <div class="flex flex-wrap items-center gap-3">
                    <div class="w-10 h-10 rounded-xl bg-emerald-50 flex items-center justify-center shrink-0"><i class="fas ${r.icon} text-emerald-600"></i></div>
                    <div class="min-w-0 flex-1">
                        <div class="flex items-center gap-2 flex-wrap">
                            <span class="font-bold text-slate-800 text-sm">${s.id}</span>
                            <span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${COT_ESTADO_COLOR[s.estado]||'bg-slate-100'}">${COT_ESTADO_LABEL[s.estado]||s.estado}</span>
                            ${chatNoLeido?'<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-red-500 text-white"><i class="fas fa-comment mr-1"></i>chat</span>':''}
                            ${pend?'<span class="px-2 py-0.5 rounded-full text-[10px] font-bold bg-red-100 text-red-600" title="Requisitos pendientes"><i class="fas fa-clipboard-list mr-1"></i>'+pend+' pendiente'+(pend===1?'':'s')+'</span>':''}
                        </div>
                        <p class="text-sm text-slate-600 mt-0.5 truncate">${escapeHTML(s.ramoNombre)} · ${escapeHTML(s.compania)} · ${escapeHTML(s.cliente.nombre)}</p>
                    </div>
                    <div class="flex items-center gap-3">
                        ${cotBarraSla(s)}
                        <div class="text-right hidden sm:block">
                            <p class="text-[11px] text-slate-400">Solicita</p>
                            <p class="text-xs font-semibold text-slate-600">${escapeHTML(s.creadoPor.nombre)}</p>
                        </div>
                        <i class="fas fa-chevron-right text-slate-300"></i>
                    </div>
                </div>
            </div>`;
        }
        function cotSetFiltro(f){ window.cotFiltro=f; render(); }
        function cotSetBusca(v){ window.cotBusca=v; const box=document.getElementById('cot-busca'); if(box){ box.focus(); } cotRenderSolo(); }
        function cotRenderSolo(){ const c=document.getElementById('main-content'); if(c && window.lastPage==='cotizaciones') c.innerHTML=renderCotizaciones(); const b=document.getElementById('cot-busca'); if(b){ b.focus(); const v=b.value; b.value=''; b.value=v; } }
        /* ---------- Analítica (procesadores) ---------- */
        function cotTabAnalitica(){
            const lista = cotListaVisible();
            const porRamo = COT_RAMOS.map(r=>{
                const ls = lista.filter(s=>s.ramo===r.id);
                const act = ls.filter(s=>['solicitud','revision','aclaracion'].includes(s.estado));
                const ret = act.filter(s=>cotSlaInfo(s).nivel==='over').length;
                const res = ls.filter(s=>(s.estado==='cotizada'||s.estado==='emitida')&&s.cotizacion&&s.cotizacion.enviadaEn);
                const prom = res.length?(res.reduce((a,s)=>a+(new Date(s.cotizacion.enviadaEn)-new Date(s.creado))/3600000,0)/res.length):null;
                return {r, n:ls.length, act:act.length, ret, prom};
            }).filter(x=>x.n>0);
            const carga = {};
            lista.filter(s=>s.asignadoA && ['solicitud','revision','aclaracion'].includes(s.estado)).forEach(s=>{ carga[s.asignadoA.nombre]=(carga[s.asignadoA.nombre]||0)+1; });
            const procesadores = (db.users||[]).filter(u=>hasRole(u,['agencia','admin','gm','desarrollador']));
            showModal(`<div class="max-w-3xl w-full bg-white rounded-2xl p-6 modal-scroll" onclick="event.stopPropagation()">
                <div class="flex items-center justify-between mb-4"><h3 class="text-lg font-bold text-slate-800"><i class="fas fa-chart-bar text-emerald-600 mr-2"></i>Analítica de cotizaciones</h3><button onclick="closeModal()" class="text-slate-400 hover:text-slate-700"><i class="fas fa-times text-lg"></i></button></div>
                ${porRamo.length? `<div class="overflow-x-auto"><table class="w-full text-sm">
                    <thead class="bg-slate-50"><tr><th class="text-left px-3 py-2 text-xs font-semibold text-slate-500 uppercase">Ramo</th><th class="px-3 py-2 text-xs font-semibold text-slate-500 uppercase">Total</th><th class="px-3 py-2 text-xs font-semibold text-slate-500 uppercase">Activas</th><th class="px-3 py-2 text-xs font-semibold text-slate-500 uppercase">Retrasadas</th><th class="px-3 py-2 text-xs font-semibold text-slate-500 uppercase">Resp. prom.</th></tr></thead>
                    <tbody class="divide-y divide-slate-100">${porRamo.map(x=>`<tr><td class="px-3 py-2 font-medium text-slate-700">${x.r.nombre}</td><td class="px-3 py-2 text-center">${x.n}</td><td class="px-3 py-2 text-center">${x.act}</td><td class="px-3 py-2 text-center ${x.ret?'text-red-600 font-bold':'text-slate-400'}">${x.ret}</td><td class="px-3 py-2 text-center">${x.prom?x.prom.toFixed(1)+' h':'—'}</td></tr>`).join('')}</tbody>
                </table></div>` : '<p class="text-slate-500 text-sm py-6 text-center">Sin datos todavía.</p>'}
                <h4 class="font-bold text-slate-700 text-sm mt-5 mb-2"><i class="fas fa-user-clock text-slate-400 mr-1"></i> Carga actual por procesador</h4>
                <div class="grid sm:grid-cols-2 gap-2">${procesadores.map(u=>{const n=carga[u.name]||0;return `<div class="flex items-center justify-between bg-slate-50 rounded-lg px-3 py-2"><span class="text-sm text-slate-600 flex items-center gap-2"><img src="${u.avatar}" class="w-6 h-6 rounded-full">${escapeHTML(u.name)}</span><span class="font-bold ${n?'text-amber-600':'text-emerald-600'}">${n}</span></div>`;}).join('')}</div>
            </div>`);
        }
        /* ---------- Configuración GM: compañías y checklist ---------- */
        function cotCfgChkRow(ramoId, c){
            return '<div class="flex items-center justify-between bg-slate-50 border border-slate-200 rounded-lg px-2.5 py-1.5 mb-1.5" data-chkk="'+escapeHTML(c.k)+'"><span class="text-sm text-slate-700">'+escapeHTML(c.t)+'</span><button onclick="cotCfgChkDel(\''+ramoId+'\', this)" class="text-xs text-red-500 hover:text-red-600" title="Quitar requisito"><i class="fas fa-trash"></i></button></div>';
        }
        function cotCfgChkAdd(ramoId){
            const inp = document.getElementById('cot-cfg-new-'+ramoId);
            const t = inp && inp.value.trim(); if(!t) return;
            const cfg = cotCfg();
            if(!cfg.checkExtra) cfg.checkExtra = {};
            const list = (cfg.checkExtra[ramoId] || (COT_CHECK_EXTRA[ramoId]||[]).slice()).slice();
            const k = 'gm_'+ramoId+'_'+(list.length+1)+'_'+Math.floor(Math.random()*10000);
            list.push({k, t});
            cfg.checkExtra[ramoId] = list; saveDB();
            const wrap = document.getElementById('cot-cfg-chk-'+ramoId);
            if(wrap) wrap.insertAdjacentHTML('beforeend', cotCfgChkRow(ramoId,{k,t}));
            inp.value=''; showToast('Requisito agregado al checklist','success');
        }
        function cotCfgChkDel(ramoId, btn){
            const cfg = cotCfg();
            const row = btn.closest('[data-chkk]'); const k = row ? row.getAttribute('data-chkk') : null;
            const list = (cfg.checkExtra && cfg.checkExtra[ramoId]) || (COT_CHECK_EXTRA[ramoId]||[]).slice();
            if(!cfg.checkExtra) cfg.checkExtra = {};
            cfg.checkExtra[ramoId] = list.filter(x=>x.k!==k);
            saveDB(); row.remove(); showToast('Requisito eliminado del checklist','info');
        }
        function cotCfgCompAdd(){
            const inp = document.getElementById('cot-cfg-comp-new');
            const n = inp && inp.value.trim(); if(!n) return;
            const cfg = cotCfg(); const list = cotCompanias();
            if(list.some(c=>c.toLowerCase()===n.toLowerCase())){ showToast('Esa compañía ya existe','error'); return; }
            list.push(n); cfg.companias = list; saveDB(); showToast('Compañía agregada: '+n,'success'); cotConfigModal();
        }
        function cotCfgCompDel(i){
            const cfg = cotCfg(); const list = cotCompanias();
            if(list.length<=1){ showToast('Debe existir al menos una compañía','error'); return; }
            const quito = list.splice(i,1);
            cfg.companias = list; saveDB(); showToast('Compañía eliminada: '+quito[0],'info'); cotConfigModal();
        }
        function cotCfgResetComps(){ const cfg = cotCfg(); cfg.companias = COT_COMPANIAS_DEFECTO.slice(); saveDB(); showToast('Lista de compañías restaurada','info'); cotConfigModal(); }
        function cotConfigModal(){
            if(!cotPuedeConfigurar()){ showToast('Solo GM/Admin/Desarrollador pueden configurar el cotizador','error'); return; }
            const comps = cotCompanias();
            const ramosHtml = COT_RAMOS.map(r=>{
                const items = cotCheckExtra(r.id);
                return `<details class="bg-white border border-slate-200 rounded-xl p-3"><summary class="cursor-pointer select-none text-sm font-bold text-slate-700"><i class="fas ${r.icon} text-emerald-600 mr-1"></i>${r.nombre} <span class="text-xs text-slate-400 font-normal">(${items.length} requisitos)</span></summary>
                    <div class="mt-2" id="cot-cfg-chk-${r.id}">${items.map(c=>cotCfgChkRow(r.id,c)).join('')}</div>
                    <div class="flex gap-2 mt-2">
                        <input id="cot-cfg-new-${r.id}" placeholder="Nuevo requisito…" class="flex-1 px-2 py-1.5 border border-slate-200 rounded-lg text-sm bg-white text-slate-900" onkeydown="if(event.key==='Enter')cotCfgChkAdd('${r.id}')">
                        <button onclick="cotCfgChkAdd('${r.id}')" class="px-3 py-1.5 bg-slate-900 text-white rounded-lg text-xs font-semibold hover:bg-slate-800"><i class="fas fa-plus"></i></button>
                    </div>
                    <p class="text-[11px] text-slate-400 mt-1">El checklist del GM reemplaza la lista del ramo: puedes agregar o quitar requisitos.</p>
                </details>`;
            }).join('');
            const ia = cotIaCfg();
            showModal(`<div class="max-w-2xl w-full bg-white rounded-2xl modal-scroll" onclick="event.stopPropagation()">
                <div class="p-6 pb-3 border-b border-slate-100 flex items-center justify-between">
                    <div><h3 class="text-lg font-bold text-slate-800"><i class="fas fa-sliders text-emerald-600 mr-2"></i>Configuración del cotizador</h3>
                    <p class="text-xs text-slate-500 mt-0.5">Exclusivo GM / Admin / Desarrollador. Los cambios aplican de inmediato para toda la agencia.</p></div>
                    <button onclick="closeModal()" class="text-slate-400 hover:text-slate-700"><i class="fas fa-times text-lg"></i></button>
                </div>
                <div class="p-6 space-y-4">
                    <div class="border border-violet-200 bg-violet-50/50 rounded-xl p-4">
                        <p class="text-xs font-bold text-violet-700 uppercase mb-2"><i class="fas fa-wand-magic-sparkles mr-1"></i> IA de análisis de pólizas</p>
                        <p class="text-[11px] text-slate-500 mb-3">Esta IA lee el documento de la póliza y lo compara punto por punto con la solicitud (tipo de seguro, asegurado, prima, suma, deducibles…). La clave se guarda solo en este navegador.</p>
                        <div class="grid sm:grid-cols-2 gap-3">
                            <div><label class="text-xs font-semibold text-slate-500">Proveedor</label>
                                <select id="cot-ia-prov" onchange="cotIaCfgProvChange()" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900">
                                    <option value="gemini" ${(ia.proveedor||'gemini')==='gemini'?'selected':''}>Google Gemini (recomendado, con capa gratuita)</option>
                                    <option value="openai" ${ia.proveedor==='openai'?'selected':''}>OpenAI</option>
                                    <option value="groq" ${ia.proveedor==='groq'?'selected':''}>Groq</option>
                                    <option value="openrouter" ${ia.proveedor==='openrouter'?'selected':''}>OpenRouter</option>
                                    <option value="custom" ${ia.proveedor==='custom'?'selected':''}>Otro (compatible OpenAI)</option>
                                </select></div>
                            <div><label class="text-xs font-semibold text-slate-500">Modelo (opcional)</label><input id="cot-ia-modelo" value="${escapeHTML(ia.modelo||'')}" placeholder="Default según proveedor" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900"></div>
                            <div class="sm:col-span-2"><label class="text-xs font-semibold text-slate-500">API Key</label><input id="cot-ia-key" type="password" value="${escapeHTML(ia.key||'')}" placeholder="Pega aquí tu API key" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900"></div>
                            <div class="sm:col-span-2" id="cot-ia-url-wrap" style="${ia.proveedor==='custom'?'':'display:none'}"><label class="text-xs font-semibold text-slate-500">URL del endpoint</label><input id="cot-ia-url" value="${escapeHTML(ia.url||'')}" placeholder="https://…/v1/chat/completions" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900"></div>
                        </div>
                        <div class="flex flex-wrap gap-2 mt-3">
                            <button onclick="cotIaCfgGuardar()" class="px-4 py-2 bg-violet-600 text-white rounded-xl text-sm font-semibold hover:bg-violet-700"><i class="fas fa-floppy-disk mr-1"></i> Guardar configuración IA</button>
                            <button onclick="cotIaProbar(this)" class="px-4 py-2 border border-violet-300 text-violet-700 rounded-xl text-sm font-semibold hover:bg-violet-100"><i class="fas fa-plug mr-1"></i> Probar conexión</button>
                        </div>
                    </div>
                    <div>
                        <p class="text-xs font-bold text-slate-600 uppercase mb-2"><i class="fas fa-building-shield text-emerald-600 mr-1"></i> Compañías aseguradoras</p>
                        <div class="flex flex-wrap gap-2 mb-2">${comps.map((c,i)=>`<span class="inline-flex items-center gap-1 bg-slate-100 border border-slate-200 rounded-full pl-3 pr-1.5 py-1 text-xs font-semibold text-slate-700">${escapeHTML(c)}<button onclick="cotCfgCompDel(${i})" class="w-5 h-5 rounded-full hover:bg-red-100 text-red-500" title="Quitar"><i class="fas fa-times text-[10px]"></i></button></span>`).join('')}</div>
                        <div class="flex flex-wrap gap-2">
                            <input id="cot-cfg-comp-new" placeholder="Nombre de la compañía…" class="flex-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900" onkeydown="if(event.key==='Enter')cotCfgCompAdd()">
                            <button onclick="cotCfgCompAdd()" class="px-4 py-2 bg-emerald-600 text-white rounded-xl text-sm font-semibold hover:bg-emerald-700"><i class="fas fa-plus mr-1"></i> Agregar</button>
                            <button onclick="cotCfgResetComps()" class="px-3 py-2 border border-slate-300 rounded-xl text-xs font-semibold text-slate-500 hover:bg-slate-50">Restaurar</button>
                        </div>
                    </div>
                    <div>
                        <p class="text-xs font-bold text-slate-600 uppercase mb-2"><i class="fas fa-clipboard-list text-emerald-600 mr-1"></i> Checklist de requisitos por ramo</p>
                        <div class="space-y-2">${ramosHtml}</div>
                    </div>
                </div>
            </div>`);
        }
        /* ---------- Crear solicitud ---------- */
        function cotModalNueva(){
            if(!(cotEsSolicitante()||cotEsProcesador())) return;
            window.cotNuevaChk = {};
            const opcionesRamo = COT_RAMOS.map(r=>`<option value="${r.id}">${r.nombre}</option>`).join('');
            showModal(`<div class="cot-nueva bg-white rounded-2xl modal-scroll" onclick="event.stopPropagation()">
                <div class="px-5 sm:px-7 lg:px-8 py-5 border-b border-slate-100 grid sm:grid-cols-[minmax(0,1fr)_auto] items-start gap-3">
                    <div><h3 class="text-lg font-bold text-slate-800"><i class="fas fa-file-circle-plus text-emerald-600 mr-2"></i>Nueva solicitud de cotización</h3>
                    <p class="text-xs text-slate-500 mt-0.5">Completa los datos y marca el checklist de requisitos; puedes adjuntar documentos.</p></div>
                    <button onclick="closeModal()" class="justify-self-end text-slate-400 hover:text-slate-700"><i class="fas fa-times text-lg"></i></button>
                </div>
                <div class="p-5 sm:p-7 lg:p-8 space-y-5">
                    <p class="text-[10px] font-bold uppercase text-slate-400 tracking-wider"><i class="fas fa-user-pen mr-1"></i> Datos del cliente</p>
                    <div class="grid sm:grid-cols-3 gap-4">
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Nombre del cliente / asegurado *</label>
                            <input id="cot-nombre" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="Nombre completo"></div>
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Edad del asegurado</label>
                            <input id="cot-edad" type="number" min="0" max="100" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="Ej. 35"></div>
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Teléfono</label>
                            <input id="cot-tel" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="10 dígitos"></div>
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Correo</label>
                            <input id="cot-email" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="cliente@correo.com"></div>
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Persona</label>
                            <select id="cot-persona" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"><option value="fisica">Persona física</option><option value="moral">Persona moral</option></select></div>
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Compañía *</label>
                            <select id="cot-compania" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm">${cotCompanias().map(c=>`<option>${c}</option>`).join('')}</select></div>
                    </div>
                    <div class="grid gap-4 sm:grid-cols-[240px_minmax(0,1fr)]">
                        <div><label class="text-xs font-semibold text-slate-500 uppercase">Ramo *</label>
                            <select id="cot-ramo" onchange="cotRamoChange()" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm">${opcionesRamo}</select></div>
                        <div class="sm:col-span-2"><label class="text-xs font-semibold text-slate-500 uppercase">Notas para el procesador</label>
                            <textarea id="cot-notas" rows="2" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm resize-none" placeholder="Contexto del cliente, urgencia, preferencias…"></textarea></div>
                    </div>
                    <div class="grid lg:grid-cols-[minmax(0,1fr)_340px] gap-5 xl:gap-6 items-start">
                        <div id="cot-campos-extra"></div>
                        <div class="space-y-3">
                            <div id="cot-check-wrap"></div>
                            <div>
                                <label class="text-xs font-semibold text-slate-500 uppercase block mb-1"><i class="fas fa-paperclip mr-1"></i> Documentos (PDF / imagen)</label>
                                <input id="cot-docs" type="file" multiple accept="image/*,.pdf" class="w-full text-sm border border-slate-200 rounded-xl px-2.5 py-1.5">
                                <p id="cot-docs-info" class="text-[11px] text-slate-400 mt-1">Sin archivos. Máx. 2 MB por archivo.</p>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="px-5 sm:px-7 lg:px-8 pb-5 sm:pb-6 pt-4 flex flex-wrap justify-end gap-2">
                    <button onclick="closeModal()" class="px-4 py-2.5 border border-slate-300 rounded-xl text-sm font-medium">Cancelar</button>
                    <button onclick="cotCrear()" class="px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-sm font-semibold hover:bg-emerald-700"><i class="fas fa-paper-plane mr-1"></i> Enviar solicitud</button>
                </div>
            </div>`);
            cotRamoChange();
            window.cotModalId='__nueva'; // protege el formulario del re-render del poll
        }
        function cotCampoHTML(c, pref){
            const pid = pref + c.k;
            const wrapOpen = c.mostrarSi ? `<div id="${pid}-wrap" style="display:none">` : '<div>';
            const wrapClose = '</div>';
            const lbl = `<label class="text-xs font-semibold text-slate-500 uppercase">${c.t}</label>`;
            if(c.tipo==='opciones'){
                if((c.opciones||[]).length>=2 && (c.opciones||[]).length<=4){
                    const btns = (c.opciones||[]).map(o=>`<button type="button" onclick="cotOptSel('${pid}','${o}')" data-valor="${o}" class="cot-opt-btn px-2.5 py-2 rounded-xl text-xs sm:text-sm font-semibold">${o}</button>`).join('');
                    return `${wrapOpen}<label class="text-xs font-semibold text-slate-500 uppercase">${c.t}</label>
                        <div class="flex flex-wrap gap-2 mt-1" id="${pid}">${btns}</div>${wrapClose}`;
                }
                return `${wrapOpen}${lbl}<select id="${pid}" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900"><option value=""></option>${(c.opciones||[]).map(o=>`<option>${o}</option>`).join('')}</select>${wrapClose}`;
            }
            if(c.tipo==='fecha')   return `${wrapOpen}${lbl}<input id="${pid}" type="date" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900">${wrapClose}`;
            if(c.tipo==='numero')  return `${wrapOpen}${lbl}<input id="${pid}" type="number" min="0" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900" placeholder="${c.ph||''}">${wrapClose}`;
            if(c.tipo==='porcentaje') return `${wrapOpen}${lbl}<div class="relative mt-1"><input id="${pid}" type="number" min="0" max="100" step="0.5" class="w-full pr-8 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900" placeholder="${c.ph||''}"><span class="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm">%</span></div>${wrapClose}`;
            if(c.tipo==='area')    return `${wrapOpen}<div class="cot-span2">${lbl}<textarea id="${pid}" rows="2" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900" placeholder="${c.ph||''}"></textarea></div>${wrapClose}`;
            return `${wrapOpen}${lbl}<input id="${pid}" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm bg-white text-slate-900" placeholder="${c.ph||''}">${wrapClose}`;
        }
        function cotRefrescarCondicional(){
            const campos = window.cotRamoActualCampos || [];
            campos.forEach(c=>{
                if(!c.mostrarSi) return;
                const w = document.getElementById('cot-f-'+c.k+'-wrap');
                if(!w) return;
                const src = document.getElementById('cot-f-'+c.mostrarSi.campo);
                const val = src ? (src.getAttribute('data-valor')||src.value||'') : '';
                w.style.display = (val===c.mostrarSi.valor) ? '' : 'none';
            });
        }
        function cotOptSel(grupoId, valor){
            const g = (typeof grupoId==='string') ? document.getElementById(grupoId) : grupoId;
            if(!g) return;
            [...g.querySelectorAll('button')].forEach(b=>b.classList.toggle('on', b.getAttribute('data-valor')===valor));
            g.setAttribute('data-valor', valor);
            cotRefrescarCondicional();
        }
        function cotVerCampo(k){ return COT_EQUIV[k] || k; }
        function cotIntegrantesHTML(pref){
            return `<div class="cot-span2"><div class="flex items-center justify-between mt-1 mb-1">
                    <label class="text-xs font-semibold text-slate-500 uppercase">Integrantes adicionales</label>
                    <button type="button" onclick="cotIntegranteAdd('${pref}')" class="text-xs font-semibold text-emerald-700 hover:underline"><i class="fas fa-plus mr-1"></i>Agregar integrante</button></div>
                <div id="${pref}integrantes" class="space-y-2"></div></div>`;
        }
        function cotIntegranteAdd(pref){
            const wrap = document.getElementById(pref+'integrantes'); if(!wrap) return;
            const i = wrap.children.length;
            const div = document.createElement('div');
            div.className = 'cot-int-row rounded-xl p-3';
            div.innerHTML = `<div class="flex items-center justify-between mb-2"><p class="text-xs font-bold text-slate-600">Integrante ${i+1}</p><button type="button" onclick="this.closest('.cot-int-row').remove();cotIntegranteReenum('${pref}')" class="text-xs text-red-500 hover:text-red-600"><i class="fas fa-trash"></i> Quitar</button></div>
                <div class="grid sm:grid-cols-2 gap-x-3 gap-y-2">
                    <div><label class="text-[10px] font-semibold text-slate-400 uppercase">Nombre</label><input name="${pref}i-n" class="w-full px-2 py-1.5 border border-slate-200 rounded-lg text-sm bg-white text-slate-900" placeholder="Nombre completo"></div>
                    <div><label class="text-[10px] font-semibold text-slate-400 uppercase">Parentesco</label><input name="${pref}i-p" class="w-full px-2 py-1.5 border border-slate-200 rounded-lg text-sm bg-white text-slate-900" placeholder="Ej. Cónyuge, Hijo(a)"></div>
                    <div><label class="text-[10px] font-semibold text-slate-400 uppercase">Fecha de nacimiento</label><input type="date" name="${pref}i-f" class="w-full px-2 py-1.5 border border-slate-200 rounded-lg text-sm bg-white text-slate-900"></div>
                    <div><label class="text-[10px] font-semibold text-slate-400 uppercase">Género</label><div class="flex flex-wrap gap-1.5 mt-0.5" name="${pref}i-g"><button type="button" onclick="cotOptSel(this.parentNode,'MASCULINO')" data-valor="MASCULINO" class="cot-opt-btn px-2.5 py-1.5 rounded-lg text-xs font-semibold">MASCULINO</button><button type="button" onclick="cotOptSel(this.parentNode,'FEMENINO')" data-valor="FEMENINO" class="cot-opt-btn px-2.5 py-1.5 rounded-lg text-xs font-semibold">FEMENINO</button></div></div>
                    <div><label class="text-[10px] font-semibold text-slate-400 uppercase">Reconocimiento de antigüedad</label><input type="date" name="${pref}i-a" class="w-full px-2 py-1.5 border border-slate-200 rounded-lg text-sm bg-white text-slate-900"></div>
                </div>`;
            wrap.appendChild(div);
        }
        function cotIntegranteReenum(pref){
            const wrap = document.getElementById(pref+'integrantes'); if(!wrap) return;
            [...wrap.children].forEach((row,idx)=>{ const p=row.querySelector('p'); if(p) p.textContent = 'Integrante '+(idx+1); });
        }
        function cotRamoChange(){
            const ramo = document.getElementById('cot-ramo').value;
            const r = cotRamo(ramo);
            const campos = COT_CAMPOS_EXTRA[ramo]||[];
            window.cotRamoActualCampos = campos;
            const pref = 'cot-f-';
            document.getElementById('cot-campos-extra').innerHTML = campos.length ? `<div class="cot-fields grid gap-3">${campos.map(c=> c.tipo==='integrantes' ? cotIntegrantesHTML(pref) : cotCampoHTML(c,pref)).join('')}</div>` : '';
            cotRefrescarCondicional();
            const items = COT_CHECK_BASE.concat(cotCheckExtra(ramo));
            window.cotNuevaChk = {};
            document.getElementById('cot-check-wrap').innerHTML = `<div class="bg-slate-50 border border-slate-200 rounded-xl p-3">
                <p class="text-xs font-bold text-slate-600 uppercase mb-2"><i class="fas fa-clipboard-check text-emerald-600 mr-1"></i> Checklist de requisitos — ${r.nombre}</p>
                <div class="space-y-1.5">${items.map(c=>`<label class="flex items-start gap-2 text-sm text-slate-700 cursor-pointer"><input type="checkbox" data-cotchk="${c.k}" data-cott="${escapeHTML(c.t)}" onchange="window.cotNuevaChk['${c.k}']=this.checked" class="mt-0.5 accent-emerald-600"><span>${c.t}</span></label>`).join('')}</div>
                <p class="text-[11px] text-slate-400 mt-2">Puedes enviar aunque falten requisitos, pero se marcarán como pendientes y pueden retrasar la cotización.</p></div>`;
        }
        function cotLeerDocs(cb){
            const inp = document.getElementById('cot-docs');
            const files = inp && inp.files ? [...inp.files] : [];
            if(!files.length) return cb([]);
            let pend = files.length; const out = [];
            let error = null;
            files.forEach(f=>{
                if(f.size > 2*1024*1024){ error = 'El archivo "'+f.name+'" supera 2 MB.'; pend--; if(!pend) cb(out); return; }
                const rd = new FileReader();
                rd.onload = e => { out.push({nombre:f.name, tipo:f.type||'application/octet-stream', dataURL:e.target.result, fecha:new Date().toISOString()}); if(--pend===0) cb(out); };
                rd.onerror = () => { if(--pend===0) cb(out); };
                rd.readAsDataURL(f);
            });
            if(error) showToast(error, 'error');
        }
        function cotCrear(){
            try{
                const nombre = document.getElementById('cot-nombre').value.trim();
                const ramo = document.getElementById('cot-ramo').value;
                const compania = document.getElementById('cot-compania').value;
                if(!nombre){ showToast('Escribe el nombre del cliente', 'error'); return; }
                if(!compania){ showToast('Elige una compañía', 'error'); return; }
                const r = cotRamo(ramo);
                const detalles = {};
                (COT_CAMPOS_EXTRA[ramo]||[]).forEach(c=>{
                    const el = document.getElementById('cot-f-'+c.k);
                    if(!el) return;
                    if(c.tipo==='opciones'){ const v = el.getAttribute('data-valor')||el.value||''; if(v) detalles[c.k]=v; }
                    else if(c.tipo==='integrantes'){
                        const rows = document.querySelectorAll('#cot-f-integrantes .cot-int-row');
                        const ints = [...rows].map(row=>({
                            nombre:(row.querySelector('[name="cot-f-i-n"]')||{}).value||'',
                            parentesco:(row.querySelector('[name="cot-f-i-p"]')||{}).value||'',
                            fechaNac:(row.querySelector('[name="cot-f-i-f"]')||{}).value||'',
                            genero:((row.querySelector('[name="cot-f-i-g"]')||{}).getAttribute('data-valor'))||'',
                            antiguedad:(row.querySelector('[name="cot-f-i-a"]')||{}).value||''
                        })).filter(x=>x.nombre||x.parentesco||x.fechaNac);
                        if(ints.length) detalles[c.k] = ints;
                    }
                    else { const v=(el.value||'').trim(); if(v) detalles[c.k]=v; }
                });
                const checklist = COT_CHECK_BASE.concat(cotCheckExtra(ramo)).map(c=>({k:c.k, t:c.t, ok:!!window.cotNuevaChk[c.k]}));
                cotLeerDocs(docs=>{
                    const pendientes = checklist.filter(c=>!c.ok).length;
                    const crear = () => {
                        const s = {
                            id: cotFolioN(),
                            ramo, ramoNombre:r.nombre, compania,
                            cliente:{ nombre, edad:document.getElementById('cot-edad').value, telefono:document.getElementById('cot-tel').value.trim(), email:document.getElementById('cot-email').value.trim(), persona:document.getElementById('cot-persona').value },
                            detalles, notas:document.getElementById('cot-notas').value.trim(),
                            checklist, docs:docs,
                            estado:'solicitud', estadoDesde:new Date().toISOString(), creado:new Date().toISOString(),
                            creadoPor:{id:currentUser.id, nombre:currentUser.name||currentUser.username, rol:currentUser.role},
                            asignadoA:null,
                            chat:[], cotizacion:null, decision:null, vistoPor:{}
                        };
                        cotDB().unshift(s);
                        s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:'Solicitud creada por '+(currentUser.name||currentUser.username)+'.', fecha:Date.now(), sistema:true});
                        notificarNuevoTramite('cot', '📄 Nueva solicitud de cotización '+s.id+' ('+s.ramoNombre+'): '+s.cliente.nombre+' · por '+(currentUser.name||currentUser.username));
                        try{ if(Array.isArray(db.notifications)) db.notifications.unshift({id:'notif-cot-'+Date.now(), userId:currentUser.id, type:'cotizacion', mensaje:'Solicitud '+s.id+' enviada al equipo de cotización', fecha:new Date().toISOString(), read:false}); }catch(e){}
                        saveDB();
                        closeModal(); window.cotFiltro='todas';
                        showToast('Solicitud '+s.id+' enviada al equipo de cotización', 'success');
                        updateBadgeCotizaciones();
                        render();
                    };
                    if(pendientes>0 && !confirm('Tienes '+pendientes+' requisito(s) sin marcar en el checklist. ¿Enviar de todas formas? La cotización puede retrasarse.')) return;
                    crear();
                });
            }catch(e){ showToast('Error: '+e.message, 'error'); }
        }
        /* ---------- Analista de cotización ---------- */
        function cotNormTxt(v){ return String(v==null?'':v).trim(); }
        function cotValidarCurp(c){ return /^[A-ZÑ][AEIOUX][A-ZÑ]{2}\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])[HM][A-Z]{2}[B-DF-HJ-NP-TV-Z]{3}[0-9A-Z]\d$/.test(c); }
        function cotAnalista(s){
            const probs = [];
            const ok = [];
            const add = (sev, tipo, detalle) => probs.push({sev, tipo, detalle});
            const chk = (detalle) => ok.push(detalle);
            // 1. Requisitos del checklist
            const sinRequisito = (s.checklist||[]).filter(c=>!c.ok);
            if(sinRequisito.length) sinRequisito.forEach(c=>add('alta','Requisito faltante', c.t));
            else chk('Checklist de requisitos completo ('+((s.checklist||[]).length)+' requisitos marcados).');
            // 2. Documentos
            if(!s.docs || !s.docs.length) add('media','Sin documentos','La solicitud no tiene documentos adjuntos; el analista no puede validar contra expediente.');
            else chk('Documentos adjuntos: '+((s.docs||[]).length)+' archivo(s).');
            (s.docs||[]).forEach(d=>{ if(!/pdf|image|jpe?g|png|webp/i.test(d.tipo||'')) add('baja','Formato inusual','El archivo "'+d.nombre+'" no es PDF ni imagen reconocible.'); });
            // 3. Datos del cliente
            const ed = parseInt(s.cliente.edad,10);
            const r = cotRamo(s.ramo);
            if(!s.cliente.edad) add('media','Dato faltante','Edad del asegurado sin capturar: afecta tarifas y viabilidad.');
            else if(isNaN(ed) || ed < r.edad[0] || ed > r.edad[1]) add('media','Fuera de rango','Edad '+s.cliente.edad+' fuera del rango asegurable típico del ramo ('+r.edad[0]+'–'+r.edad[1]+' años). Confirmar con la compañía.');
            else chk('Edad '+ed+' dentro del rango asegurable del ramo ('+r.edad[0]+'–'+r.edad[1]+' años).');
            if(!s.cliente.telefono || s.cliente.telefono.replace(/[^0-9]/g,'').length < 10) add('media','Dato inválido','Teléfono del cliente incompleto (menos de 10 dígitos).');
            else chk('Teléfono del cliente capturado a 10 dígitos.');
            if(!s.cliente.email || !s.cliente.email.includes('@')) add('media','Dato inválido','Correo electrónico del cliente inválido o faltante.');
            else chk('Correo electrónico del cliente con formato válido.');
            if(/[0-9]/.test(s.cliente.nombre||'')) add('baja','Dato sospechoso','El nombre del cliente contiene números: revisar captura.');
            else chk('Nombre del cliente capturado: "'+s.cliente.nombre+'".');
            // 4. Campos específicos del ramo: faltantes + validaciones por tipo
            const d = s.detalles||{};
            const camposReq = COT_CAMPOS_EXTRA[s.ramo]||[];
            camposReq.forEach(c=>{
                if(c.mostrarSi && d[c.mostrarSi.campo]!==c.mostrarSi.valor) return; // condicional no aplica
                const v = d[c.k];
                const vacio = (c.tipo==='integrantes') ? (!Array.isArray(v) || !v.length) : !cotNormTxt(v);
                if(vacio){ add('alta','Dato requerido', c.t+' sin capturar.'); return; }
                if(c.tipo==='numero'){
                    if(c.k==='deducible' && parseFloat(v)<=0) add('media','Dato inválido','Deducible debe ser mayor a 0.');
                    if(c.k==='cp' && String(v).replace(/[^0-9]/g,'').length!==5) add('media','Dato inválido','Código postal debe tener 5 dígitos (se capturó "'+v+'").');
                }
                if(c.tipo==='porcentaje' && (parseFloat(v)<0 || parseFloat(v)>100)) add('media','Dato inválido','Coaseguro fuera de rango (0–100%): se capturó "'+v+'".');
                if(c.k==='curp' && !cotValidarCurp(String(v).toUpperCase())) add('media','Dato inválido','CURP con formato inválido: "'+v+'". Verificar contra la CURP oficial.');
                if(c.tipo==='fecha' && new Date(v) > new Date()) add('media','Dato inválido', c.t+': la fecha no puede ser futura.');
                if(c.tipo==='integrantes' && Array.isArray(v)){
                    v.forEach((it,i)=>{
                        if(!cotNormTxt(it.nombre)) add('media','Dato faltante','Integrante '+(i+1)+': nombre sin capturar.');
                        if(!cotNormTxt(it.fechaNac)) add('baja','Dato faltante','Integrante '+(i+1)+': fecha de nacimiento sin capturar.');
                        if(it.antiguedad && new Date(it.antiguedad) > new Date()) add('media','Dato inválido','Integrante '+(i+1)+': reconocimiento de antigüedad con fecha futura.');
                    });
                }
            });
            if(d.perfil && !COT_PERFILES.includes(d.perfil)) add('media','Dato inválido','Perfil "'+d.perfil+'" no reconocido (usa CONSERVADOR, DINÁMICO o INVERSIONISTA).');
            if(d.estrategia && !['PPR','SOLO INVERSIÓN'].includes(d.estrategia)) add('media','Dato inválido','Estrategia "'+d.estrategia+'" no reconocida (usa PPR o SOLO INVERSIÓN).');
            if(d.tipo==='EDUCATIVO' && (!d.menor_edad || !d.menor_genero)) add('alta','Dato requerido','Tipo EDUCATIVO: captura género y edad del menor.');
            if(d.tipo==='EDUCATIVO' && d.menor_edad){ const me=parseInt(d.menor_edad,10); if(!isNaN(me) && me>=18) add('media','Fuera de rango','Edad del menor ('+me+') corresponde a un adulto: verificar el plan educativo.'); }
            if(d.app && d.app!=='NO') add('media','Uso comercial','El vehículo trabaja con '+d.app+': verificar que la cotización incluya cobertura de transporte público/aplicación.');
            if(d.procedencia && d.procedencia!=='MEXICANO') add('media','Origen extranjero','Vehículo '+d.procedencia+': confirmar que la compañía cotice amparo/legalización.');
            if(d.fumador==='FUMADOR') add('baja','Tarifa especial','Asegurado declarado FUMADOR: la tarifa puede tener recargo; confirmar con la compañía.');
            if(d.coaseguro && parseFloat(d.coaseguro)===0) add('baja','Sin coaseguro','Coaseguro en 0%: verificar que la cotización refleje esa condición.');
            // 5. Reglas de negocio por tipo
            if(r.colectivo && d.integrantes){
                const n = parseInt(String(Array.isArray(d.integrantes)?d.integrantes.length:d.integrantes).replace(/[^0-9]/g,''),10);
                if(!isNaN(n) && n < 5) add('alta','Regla de colectivo','Los colectivos normalmente requieren mínimo 5 integrantes; se registraron '+n+'.');
            }
            // 6. Contradicciones con la cotización cargada (si existe)
            const q = s.cotizacion;
            const rev = { fecha:new Date().toISOString(), por:{id:currentUser.id, nombre:currentUser.name||currentUser.username}, coincidencias:[], diferencias:[], sinCotejar:[], extraccion:{}, documentos:{} };
            if(q){
                if(!q.primaAnual || parseFloat(q.primaAnual)<=0) add('alta','Cotización inválida','Prima anual vacía o no positiva.');
                else chk('Prima anual capturada: $'+Number(q.primaAnual).toLocaleString('es-MX',{minimumFractionDigits:2})+' MXN.');
                if(!q.formaPago) add('media','Cotización incompleta','Forma de pago no indicada en la cotización.');
                else chk('Forma de pago indicada: '+q.formaPago+'.');
                if(!q.vigencia) add('baja','Cotización incompleta','Vigencia del documento no indicada.');
                else chk('Vigencia del documento: '+q.vigencia+'.');
                if(!q.archivo || !q.archivo.dataURL) add('alta','Cotización inválida','No se adjuntó el documento de la cotización.');
                else chk('Póliza/documento de cotización adjunto ("'+(q.archivo.nombre||'archivo')+'").');
                if(q.asegurado && cotNormTxt(q.asegurado)){
                    const a=cotNormTxt(q.asegurado).toLowerCase(), b=cotNormTxt(s.cliente.nombre).toLowerCase();
                    if(b && !(a.includes(b)||b.includes(a))) add('alta','Inconsistencia','El asegurado en la cotización ("'+q.asegurado+'") no coincide con el cliente de la solicitud ("'+s.cliente.nombre+'").');
                    else chk('Asegurado en póliza ("'+q.asegurado+'") coincide con el cliente solicitado.');
                }
                if(q.compania && s.compania && s.compania!=='Sin preferencia' && q.compania!==s.compania) add('media','Inconsistencia','La compañía cotizada ('+q.compania+') difiere de la solicitada ('+s.compania+'). Verificar autorización.');
                else chk('Compañía ('+(q.compania||s.compania)+') coincide con la solicitada.');
                // 6b. Cruce póliza real vs datos solicitados: extrae el dato de la póliza (cotejo manual o texto pegado) y compara punto por punto
                const P = q.polinizaTexto || q.polizaTexto || '';
                const gk = (k)=>{ const el=document.getElementById('cot-cmp-'+k); return el ? cotNormTxt(el.value) : null; };
                COT_PARES.forEach(k=>{
                    const sol = (k==='nombre'||k==='edad') ? cotNormTxt(k==='nombre'?s.cliente.nombre:s.cliente.edad) : cotNormTxt(d[k]);
                    if(!sol) return; // el ramo no lo pide
                    let pol = gk(k); // cotejo manual (input del procesador)
                    if((pol===null||pol==='') && P){ const ex=cotExtraerDato(P,k); if(ex) pol=ex; } // extracción automática del texto de la póliza
                    if(pol===null || pol===''){ rev.sinCotejar.push(cotVerCampo(k)); return; } // no capturado: validación manual pendiente
                    rev.extraccion[k] = String(pol);
                    const norm = (v)=>String(v).toUpperCase().replace(/\s+/g,' ').replace(/[^A-ZÑ0-9.%$\/\- ]/g,'').trim();
                    const num = (v)=>{ const m=String(v).replace(/[^0-9.,]/g,'').replace(/,(\d{3})/g,'$1').replace(',','.'); const f=parseFloat(m); return isNaN(f)?null:f; };
                    let mismo = norm(sol)===norm(pol);
                    if(!mismo){ const ns=num(sol), np=num(pol); if(ns!==null && np!==null && ns===np) mismo=true; } // $1,500.00 == 1500
                    if(mismo){ rev.coincidencias.push({campo:k, etiqueta:cotVerCampo(k), solicitud:sol, poliza:String(pol)}); chk(cotVerCampo(k)+': coincide con la póliza ("'+pol+'").'); }
                    else { rev.diferencias.push({campo:k, etiqueta:cotVerCampo(k), solicitud:sol, poliza:String(pol)}); add('alta','No coincide', cotVerCampo(k)+': póliza dice "'+pol+'" y la solicitud "'+sol+'". Corregir antes de enviar.'); }
                });
                // 6c. Coberturas solicitadas vs póliza (texto libre)
                if(cotNormTxt(d.coberturas)){
                    const cobSol = cotNormTxt(d.coberturas);
                    let cobPol = gk('coberturas');
                    if((cobPol===null||cobPol==='') && P){ const ex=cotExtraerDato(P,'coberturas'); if(ex) cobPol=ex; }
                    if(cobPol===null || cobPol==='') rev.sinCotejar.push('Coberturas adicionales');
                    else rev.extraccion['coberturas'] = cobPol;
                    const faltan = cobSol.split(/[,;\n]/).map(x=>x.trim()).filter(x=>x.length>3 && !cotNormTxt(cobPol).toUpperCase().includes(x.toUpperCase().split(' ')[0]));
                    if(faltan.length) add('media','Cobertura faltante','La póliza no menciona: '+faltan.join(', ')+'. Confirmar endosos/coberturas adicionales.');
                    else chk('Coberturas adicionales solicitadas presentes en la póliza.');
                }
                // 6d. Documentos: requeridos según ramo vs adjuntos
                const reqDocs = [
                    {k:'identificacion', t:'INE / identificación oficial', ramo:null, pat:/(ine|identificaci|credencial|ife)/i},
                    {k:'comprobante', t:'Comprobante de domicilio', ramo:null, pat:/(comprobante|domicilio|cfE?e?\s*de.*luz|cfe)/i},
                    {k:'salud', t:'Cuestionario de salud', ramo:['gmm-ind','vida-ind'], pat:/(salud|m[eé]dico|cuestionario)/i},
                    {k:'circulacion', t:'Tarjeta de circulación', ramo:['auto-ind'], pat:/(circulaci|tarjeta)/i},
                    {k:'licencia', t:'Licencia de conducir', ramo:['auto-ind'], pat:/(licencia)/i}
                ];
                const nombresDocs = (s.docs||[]).map(x=>cotNormTxt(x.nombre)).join(' | ');
                const docsRequeridos = reqDocs.filter(x=>!x.ramo || x.ramo.includes(s.ramo));
                const sinDoc = docsRequeridos.filter(x=>!x.pat.test(nombresDocs));
                rev.documentos = { requeridos: docsRequeridos.map(x=>x.t), faltantes: sinDoc.map(x=>x.t), adjuntos: (s.docs||[]).map(x=>x.nombre) };
                sinDoc.forEach(x=>add('media','Documento faltante','No se adjuntó '+x.t+' (búscalo en el expediente o pídelo al agente).'));
                if(!sinDoc.length && (s.docs||[]).length) chk('Expediente con documentos base del ramo ('+(s.docs||[]).length+' archivo(s)).');
            }
            let score = 100; probs.forEach(p=>{ score -= COT_PESO[p.sev]; });
            score = Math.max(0, score);
            const altas = probs.filter(p=>p.sev==='alta').length;
            const resultado = { score, aprobado: score>=70 && altas===0, problemas:probs, confirmaciones:ok, fecha:new Date().toISOString() };
            if(q){ resultado.revision = rev; }
            return resultado;
        }
        /* ---------- Extracción de datos desde el texto de la póliza ---------- */
        const COT_EXTRA_PAT = [
            {k:'nombre', pat:/asegurado[:\s]*([A-ZÁÉÍÓÚÑÜ][A-Za-zÁÉÍÓÚÑÜáéíóúñü ]{4,60}?)(?=[.,;\n]|\s{2,}|$)/i},
            {k:'edad', pat:/edad[:\s]*(\d{1,3})/i},
            {k:'cp', pat:/(?:c\.?p\.?|c[oó]digo postal)[:\s]*(\d{5})/i},
            {k:'suma', pat:/suma(?:\s+asegurada)?[:\s]*\$?\s*([\d,]+(?:\.\d+)?)/i},
            {k:'deducible', pat:/deducible[:\s]*\$?\s*([\d,]+(?:\.\d+)?)\s*(?:usd|mxn|pesos)?/i},
            {k:'coaseguro', pat:/coaseguro[:\s]*(\d+(?:\.\d+)?)\s*%/i},
            {k:'plazo', pat:/plazo[:\s]*(\d{1,3})\s*(?:a[ñn]os)?/i},
            {k:'aportacion', pat:/aportaci[oó]n(?:\s+mensual)?[:\s]*\$?\s*([\d,]+(?:\.\d+)?)/i},
            {k:'gama', pat:/gama[:\s]*([A-Za-zÁÉÍÓÚÑÜáéíóúñü +]{3,40})/i},
            {k:'prima', pat:/prima(?:\s+(?:anual|total))?[:\s]*\$?\s*([\d,]+(?:\.\d+)?)/i},
            {k:'vigencia', pat:/vigencia[:\s]*([A-Za-z0-9ÁÉÍÓÚÑÜáéíóúñü /]{3,40})/i}
        ];
        function cotExtraerDato(texto, k){
            if(!texto) return null;
            const t = String(texto).replace(/\s+/g,' ');
            const def = COT_EXTRA_PAT.find(x=>x.k===k);
            if(def){ const m = t.match(def.pat); if(m && m[1]) return m[1].trim(); }
            // Palabra clave genérica: busca "clave: valor"
            const lbl = cotVerCampo(k).replace(/[^A-Za-zÁÉÍÓÚÑÜáéíóúñü ]/g,'').trim();
            if(lbl.length>=4){ const m2 = t.match(new RegExp(lbl+'[:\\s]*([^;\\n|]{1,60})','i')); if(m2 && m2[1] && cotNormTxt(m2[1])) return m2[1].trim(); }
            return null;
        }
        /* ---------- Análisis IA de la póliza (documento vs solicitud) ---------- */
        function cotIaCfg(){
            try{ const c=cotCfg(); if(!c.ia) c.ia={proveedor:'gemini', modelo:'', key:'', url:''}; return c.ia; }catch(e){ return {proveedor:'gemini', modelo:'', key:'', url:''}; }
        }
        function cotIaEndpoint(prov, cfg){
            const modelos = { gemini:'gemini-2.0-flash', openai:'gpt-4o-mini', groq:'llama-3.3-70b-versatile', openrouter:'google/gemini-2.0-flash-001' };
            const modelo = cfg.modelo || modelos[prov];
            if(prov==='gemini') return { url:'https://generativelanguage.googleapis.com/v1beta/models/'+modelo+':generateContent', modelo, estilo:'gemini' };
            if(prov==='openai') return { url:'https://api.openai.com/v1/chat/completions', modelo, estilo:'openai' };
            if(prov==='groq') return { url:'https://api.groq.com/openai/v1/chat/completions', modelo, estilo:'openai' };
            if(prov==='openrouter') return { url:'https://openrouter.ai/api/v1/chat/completions', modelo, estilo:'openai' };
            return { url:cfg.url||'', modelo, estilo:'openai' };
        }
        function cotIaPrompt(s){
            const d = s.detalles||{};
            const lista = [];
            lista.push('nombre='+(s.cliente.nombre||''));
            if(s.cliente.edad) lista.push('edad='+s.cliente.edad);
            COT_PARES.forEach(k=>{ if(k==='nombre'||k==='edad') return; const v=d[k]; if(Array.isArray(v)||!cotNormTxt(v)) return; lista.push(k+'='+v); });
            if(d.coberturas) lista.push('coberturas='+d.coberturas);
            return [
                'Eres un analista de seguros mexicano. Recibes: (1) los datos de una SOLICITUD de cotización y (2) el TEXTO COMPLETO de una PÓLIZA o cotización emitida por una aseguradora.',
                'Tu trabajo: analizar el documento a detalle y compararlo punto por punto contra la solicitud para VALIDAR si la póliza corresponde exactamente a lo que se pidió.',
                'Debes detectar errores, diferencias y contradicciones. Ejemplos: si la solicitud es de un seguro de Gastos Médicos Mayores individual pero el documento corresponde a un seguro de Autos individual, eso es un error de tipo de seguro y debe reportarse como critico.',
                'También compara: nombre del asegurado, edad, suma asegurada, prima anual, deducible, coaseguro, gama hospitalaria, tabulador, zona/cp, forma de pago, vigencia, coberturas adicionales y cualquier otro dato solicitado que aparezca en el documento.',
                'Datos solicitados:',
                lista.join('\n'),
                '',
                'Responde SOLO con un objeto JSON válido (sin markdown, sin texto extra) con esta forma exacta:',
                '{"tipoSeguroDoc":"<tipo de seguro que dice el documento>", "ramoCoincide":true|false, "resumen":"<2-3 frases en español>", "diferencias":[{"campo":"<campo>", "solicitud":"<valor solicitado>", "poliza":"<valor en el documento>", "severidad":"critica|media|baja", "explicacion":"<por qué es error>"}], "datosCorrectos":["<campo verificado sin problema>"], "sinInformacion":["<dato solicitado que no aparece en el documento>"], "recomendaciones":["<acción concreta para el analista>"]}',
                'Reglas: usa exactamente las etiquetas de campo tal como aparecen en "Datos solicitados". Si un dato no aparece en el documento va en "sinInformacion", no lo inventes. Severidad "critica" = la póliza no sirve tal cual (ramo distinto, asegurado distinto, prima o suma muy diferente); "media" = diferencia corregible; "baja" = cosmética o ambigua.'
            ].join('\n');
        }
        function cotIaParse(txt){
            try{
                let t = String(txt||'').trim();
                const m = t.match(/```(?:json)?\s*([\s\S]*?)```/); if(m) t = m[1].trim();
                const i = t.indexOf('{'), j = t.lastIndexOf('}');
                if(i>=0 && j>i) t = t.slice(i, j+1);
                const o = JSON.parse(t);
                if(!o || typeof o!=='object') return null;
                if(!Array.isArray(o.diferencias)) o.diferencias = [];
                if(!Array.isArray(o.datosCorrectos)) o.datosCorrectos = [];
                if(!Array.isArray(o.sinInformacion)) o.sinInformacion = [];
                if(!Array.isArray(o.recomendaciones)) o.recomendaciones = [];
                return o;
            }catch(e){ return null; }
        }
        function cotIaTextoPoliza(){
            const el = document.getElementById('cot-q-poltxt') || document.getElementById('cot-r-poltxt');
            return el ? el.value.trim() : '';
        }
        function cotIaArchivoBase64(file){
            return new Promise((res, rej)=>{ const rd = new FileReader(); rd.onload = e=>res(String(e.target.result).split(',')[1]); rd.onerror = rej; rd.readAsDataURL(file); });
        }
        function cotIaArchivoDataURL(file){
            return new Promise((res, rej)=>{ const rd = new FileReader(); rd.onload = e=>res(e.target.result); rd.onerror = rej; rd.readAsDataURL(file); });
        }
        async function cotIaDocCargada(){
            const inp = document.getElementById('cot-ia-doc') || document.getElementById('cot-ia-doc-r');
            const info = document.getElementById('cot-ia-doc-info');
            if(!inp || !inp.files || !inp.files.length){ window.cotIaDocScan = null; if(info) info.textContent='Opcional: si no cargas documento, la IA analiza el texto pegado.'; return; }
            const f = inp.files[0];
            if(f.size > 8*1024*1024){ showToast('El documento supera 8 MB', 'error'); inp.value=''; return; }
            if(info) info.textContent = 'Leyendo «'+f.name+'»…';
            try{
                if(/pdf/i.test(f.type||'') || /\.pdf$/i.test(f.name||'')){
                    if(!window.pdfjsLib){
                        await new Promise((res, rej)=>{ const sc=document.createElement('script'); sc.src='https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js'; sc.onload=res; sc.onerror=rej; document.head.appendChild(sc); });
                        window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
                    }
                    const buf = await f.arrayBuffer();
                    const pdf = await window.pdfjsLib.getDocument({data:buf}).promise;
                    let out = '';
                    const maxPag = Math.min(pdf.numPages, 10);
                    for(let i=1; i<=maxPag; i++){ const page = await pdf.getPage(i); const tc = await page.getTextContent(); out += tc.items.map(it=>it.str).join(' ') + '\n'; }
                    out = out.trim();
                    const pol = document.getElementById('cot-q-poltxt') || document.getElementById('cot-r-poltxt');
                    if(pol && out) pol.value = out;
                    if(out){ window.cotIaDocScan = null; if(info) info.textContent = '«'+f.name+'» leído ('+pdf.numPages+' pág.): texto cargado abajo, listo para la IA.'; }
                    else { window.cotIaDocScan = f; if(info) info.textContent = '«'+f.name+'» parece escaneado (sin texto): la IA de visión lo analizará al pulsar «Analizar con IA».'; }
                } else {
                    window.cotIaDocScan = f;
                    if(info) info.textContent = 'Imagen «'+f.name+'» lista: la IA de visión la analizará al pulsar «Analizar con IA».';
                }
            }catch(e){ if(info) info.textContent = 'No se pudo leer el documento: '+e.message; }
        }
        async function cotIaExtraerPdfSiHaceFalta(s, txt){
            if(txt && txt.length>80) return txt;
            const q = s.cotizacion; if(!q || !q.archivo || !q.archivo.dataURL) return txt;
            if(!/pdf/i.test(q.archivo.tipo||'') && !/\.pdf$/i.test(q.archivo.nombre||'')) return txt;
            try{
                if(!window.pdfjsLib){
                    await new Promise((res, rej)=>{
                        const sc = document.createElement('script');
                        sc.src = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js';
                        sc.onload = res; sc.onerror = rej; document.head.appendChild(sc);
                    });
                    window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js';
                }
                const base64 = q.archivo.dataURL.split(',')[1]; if(!base64) return txt;
                const bytes = Uint8Array.from(atob(base64), c=>c.charCodeAt(0));
                const pdf = await window.pdfjsLib.getDocument({data:bytes}).promise;
                let out = '';
                const maxPag = Math.min(pdf.numPages, 10);
                for(let i=1; i<=maxPag; i++){
                    const page = await pdf.getPage(i);
                    const tc = await page.getTextContent();
                    out += tc.items.map(it=>it.str).join(' ') + '\n';
                }
                return out.trim() || txt;
            }catch(e){ return txt; }
        }
        async function cotIaAnalizar(id, btn){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            const cfg = cotIaCfg();
            const prevBtn = btn ? btn.innerHTML : '';
            const setEstado = (ic, msg)=>{ if(btn){ btn.disabled=true; btn.innerHTML='<i class="fas '+ic+' mr-1"></i> '+msg; } };
            try{
                if(!cfg.key){
                    const r = cotIaLocal(s);
                    cotIaRender(s, r, 'Modo local (sin clave IA): verifica que el ramo del documento coincida con la solicitud.');
                    showToast('Sin clave de IA configurada: análisis local básico. Configúrala en Cotizaciones → Configurar.', 'info');
                    return;
                }
                setEstado('fa-spinner fa-spin', 'Leyendo documento…');
                let texto = cotIaTextoPoliza();
                texto = await cotIaExtraerPdfSiHaceFalta(s, texto);
                const docScan = window.cotIaDocScan || null;
                if(cfg.proveedor==='groq' && docScan) throw new Error('Groq no soporta imágenes/PDF escaneados: usa Gemini u OpenAI, o pega el texto.');
                if(!texto && !docScan){
                    setEstado('fa-triangle-exclamation', 'Sin documento');
                    showToast('Carga el documento de la póliza o pega su texto para analizar.', 'error');
                    if(btn){ btn.disabled=false; btn.innerHTML=prevBtn; }
                    return;
                }
                setEstado('fa-spinner fa-spin', 'La IA está analizando el documento…');
                const ep = cotIaEndpoint(cfg.proveedor, cfg);
                const promptTxt = cotIaPrompt(s) + (texto ? ('\n\nTEXTO DEL DOCUMENTO:\n'+texto.slice(0,60000)) : '\n\n(El documento se envía adjunto; analízalo a detalle.)');
                let cuerpo, headers = {'Content-Type':'application/json'};
                if(ep.estilo==='gemini'){
                    headers['x-goog-api-key'] = cfg.key;
                    const parts = [{text: promptTxt}];
                    if(docScan) parts.push({ inline_data:{ mime_type: docScan.type||'application/pdf', data: await cotIaArchivoBase64(docScan) } });
                    cuerpo = { contents:[{ parts }], generationConfig:{ temperature:0.2, responseMimeType:'application/json' } };
                } else {
                    headers['Authorization'] = 'Bearer '+cfg.key;
                    const userContent = [{type:'text', text: promptTxt}];
                    if(docScan) userContent.push({type:'image_url', image_url:{ url: await cotIaArchivoDataURL(docScan) }});
                    cuerpo = { model: ep.modelo, temperature:0.2, response_format:{type:'json_object'}, messages:[{role:'system', content:'Responde SOLO con el objeto JSON pedido.'},{role:'user', content: userContent}] };
                    if(provExtra(cfg)) headers['HTTP-Referer'] = location.origin;
                }
                const resp = await fetch(ep.url, { method:'POST', headers, body:JSON.stringify(cuerpo) });
                if(!resp.ok){
                    const detalle = await resp.text().catch(()=>'');
                    throw new Error('HTTP '+resp.status+(detalle?(' — '+detalle.slice(0,200)):''));
                }
                const js = await resp.json();
                const raw = ep.estilo==='gemini' ? (((js.candidates||[])[0]||{}).content||{}).parts : ((js.choices||[])[0]||{}).message;
                const salida = Array.isArray(raw) ? raw.map(p=>p.text||'').join('') : ((raw||{}).content||'');
                const parsed = cotIaParse(salida);
                if(!parsed) throw new Error('La IA no devolvió JSON válido');
                cotIaRender(s, parsed, 'Análisis IA ('+ep.modelo+') del documento «'+((s.cotizacion&&s.cotizacion.archivo&&s.cotizacion.archivo.nombre)||'texto pegado')+'».');
                showToast('Análisis IA completado: '+parsed.diferencias.length+' diferencia(s) detectada(s)', parsed.ramoCoincide===false?'warning':'success');
            }catch(e){
                setEstado('fa-circle-exclamation', 'Error');
                showToast('Error del análisis IA: '+e.message, 'error');
                if(btn){ btn.disabled=false; btn.innerHTML=prevBtn; }
            }
        }
        function provExtra(cfg){ return cfg.proveedor==='openrouter'; }
        function cotIaCfgProvChange(){
            const p = document.getElementById('cot-ia-prov');
            const w = document.getElementById('cot-ia-url-wrap');
            if(p && w) w.style.display = (p.value==='custom') ? '' : 'none';
        }
        function cotIaCfgGuardar(){
            const cfg = cotIaCfg();
            cfg.proveedor = (document.getElementById('cot-ia-prov')||{}).value || 'gemini';
            cfg.modelo = ((document.getElementById('cot-ia-modelo')||{}).value||'').trim();
            cfg.key = ((document.getElementById('cot-ia-key')||{}).value||'').trim();
            cfg.url = ((document.getElementById('cot-ia-url')||{}).value||'').trim();
            saveDB();
            showToast('Configuración de IA guardada', 'success');
        }
        async function cotIaProbar(btn){
            cotIaCfgGuardar();
            const cfg = cotIaCfg();
            if(!cfg.key){ showToast('Pega tu API key primero', 'error'); return; }
            const prev = btn.innerHTML; btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin mr-1"></i> Probando…';
            try{
                const ep = cotIaEndpoint(cfg.proveedor, cfg);
                let resp;
                if(ep.estilo==='gemini'){
                    resp = await fetch(ep.url+'?key='+encodeURIComponent(cfg.key), { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({ contents:[{parts:[{text:'Responde únicamente: OK'}]}] }) });
                } else {
                    resp = await fetch(ep.url, { method:'POST', headers:{'Content-Type':'application/json','Authorization':'Bearer '+cfg.key}, body:JSON.stringify({ model:ep.modelo, messages:[{role:'user', content:'Responde únicamente: OK'}], max_tokens:10 }) });
                }
                if(!resp.ok) throw new Error('HTTP '+resp.status);
                showToast('Conexión OK con '+ep.modelo, 'success');
            }catch(e){ showToast('Sin conexión: '+e.message, 'error'); }
            btn.disabled = false; btn.innerHTML = prev;
        }
        function cotIaLocal(s){
            const q = s.cotizacion||{};
            const qt = String(q.polinizaTexto||q.polizaTexto||cotIaTextoPoliza()||'').toUpperCase();
            const patrones = [
                {id:'vida-ind', nom:'VIDA INDIVIDUAL', pat:/VIDA\s+INDIVIDUAL|SEGURO\s+DE\s+VIDA/},
                {id:'gmm-ind', nom:'GMM INDIVIDUAL (Gastos Médicos Mayores)', pat:/GASTOS\s+M[ÉE]DICOS|GMM/},
                {id:'auto-ind', nom:'AUTO INDIVIDUAL', pat:/AUTOS?\s+INDIVIDUAL|SEGURO\s+DE\s+AUTOS|PÓLIZA\s+DE\s+AUTOS/},
                {id:'danos', nom:'DAÑOS / PROPIEDAD', pat:/DA[ÑN]OS|INCENDIO|PROPIEDAD/},
                {id:'inv-cont', nom:'INVERSIÓN', pat:/INVERSI|PPR|PLAN PERSONAL DE RETIRO/}
            ];
            const cand = patrones.filter(p=>p.pat.test(qt));
            const esperado = s.ramoNombre||'';
            const difs = [];
            if(qt){
                const hay = cand.length? cand.map(c=>c.nom).join(', ') : 'no identificado en el texto';
                const ok = cand.some(c=>c.id===s.ramo) || (s.ramo==='vida-col' && cand.some(c=>c.id==='vida-ind')) || (s.ramo==='gmm-col' && cand.some(c=>c.id==='gmm-ind')) || (s.ramo==='auto-col' && cand.some(c=>c.id==='auto-ind'));
                if(!ok) difs.push({campo:'Tipo de seguro', solicitud:esperado, poliza:hay, severidad:'critica', explicacion:'El documento parece corresponder a un tipo de seguro distinto al solicitado ('+esperado+'). Verifica que se cargó el documento correcto.'});
            }
            ['suma','deducible','coaseguro','gama','cp'].forEach(k=>{
                const sol = cotNormTxt((s.detalles||{})[k]); if(!sol) return;
                const pol = cotExtraerDato(qt,k);
                if(pol && cotNormTxt(pol).toUpperCase()!==sol.toUpperCase()) difs.push({campo:cotVerCampo(k), solicitud:sol, poliza:pol, severidad:'media', explicacion:'El texto del documento menciona un valor distinto al solicitado.'});
            });
            return { tipoSeguroDoc: qt? (cand.length? cand[0].nom : 'no identificado') : 'sin texto del documento', ramoCoincide: difs.every(x=>x.campo!=='Tipo de seguro'), resumen: qt? 'Análisis local: comparación por palabras clave y extracción de datos.' : 'No hay texto del documento para analizar.', diferencias:difs, datosCorrectos:[], sinInformacion:[], recomendaciones:['Configura una clave de IA en Cotizaciones → Configurar para un análisis completo del documento.'] };
        }
        function cotIaHtml(d, fuente){
            const crit = (d.diferencias||[]).filter(x=>x.severidad==='critica').length;
            const nivel = (d.ramoCoincide===false || crit>0) ? ['CRÍTICO','bg-red-100 text-red-700 border-red-300','fa-circle-xmark'] : (d.diferencias.length? ['REVISAR','bg-amber-100 text-amber-700 border-amber-300','fa-triangle-exclamation'] : ['SIN DIFERENCIAS','bg-emerald-100 text-emerald-700 border-emerald-300','fa-circle-check']);
            const fila = (x)=>'<div class="border rounded-lg px-3 py-2 text-xs '+(x.severidad==='critica'?'bg-red-50 border-red-200 text-red-700':(x.severidad==='media'?'bg-amber-50 border-amber-200 text-amber-700':'bg-slate-50 border-slate-200 text-slate-600'))+'"><b>'+escapeHTML(x.campo||'—')+':</b> solicitud "'+escapeHTML(x.solicitud||'—')+'" vs póliza "'+escapeHTML(x.poliza||'—')+'"'+(x.explicacion?' — '+escapeHTML(x.explicacion):'')+'</div>';
            const lista = (arr, ic, cls)=>(arr||[]).map(t=>'<p class="text-xs '+cls+'"><i class="fas '+ic+' mr-1"></i>'+escapeHTML(t)+'</p>').join('');
            return '<div class="border-2 rounded-xl p-4 mb-3 '+(nivel[1].split(' ')[0].replace('bg-','border-'))+'" id="cot-ia-bloque">'
                + '<div class="flex items-center justify-between mb-2"><p class="text-xs font-bold uppercase '+nivel[1]+'"><i class="fas fa-wand-magic-sparkles mr-1"></i> Análisis IA del documento</p>'
                + '<span class="inline-block px-2.5 py-0.5 rounded-full text-[10px] font-bold border '+nivel[1]+'"><i class="fas '+nivel[2]+' mr-1"></i>'+nivel[0]+'</span></div>'
                + (fuente? '<p class="text-[11px] text-slate-500 mb-2">'+escapeHTML(fuente)+'</p>' : '')
                + (d.tipoSeguroDoc? '<p class="text-xs text-slate-700 mb-1"><b>Tipo de seguro en el documento:</b> '+escapeHTML(d.tipoSeguroDoc)+' — '+(d.ramoCoincide===false?'<span class="text-red-600 font-bold">NO coincide con lo solicitado</span>':'<span class="text-emerald-600 font-semibold">coincide con lo solicitado</span>')+'</p>' : '')
                + (d.resumen? '<p class="text-xs text-slate-600 mb-2">'+escapeHTML(d.resumen)+'</p>' : '')
                + (d.diferencias.length? '<p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Diferencias ('+d.diferencias.length+')</p><div class="space-y-1.5 mb-2">'+d.diferencias.map(fila).join('')+'</div>' : '')
                + (d.datosCorrectos.length? '<p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Datos correctos</p><div class="flex flex-wrap gap-1 mb-2">'+d.datosCorrectos.map(t=>'<span class="text-[11px] bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full px-2 py-0.5">'+escapeHTML(t)+'</span>').join('')+'</div>' : '')
                + (d.sinInformacion.length? '<p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Sin información en el documento</p><div class="flex flex-wrap gap-1 mb-2">'+d.sinInformacion.map(t=>'<span class="text-[11px] bg-slate-50 text-slate-500 border border-slate-200 rounded-full px-2 py-0.5">'+escapeHTML(t)+'</span>').join('')+'</div>' : '')
                + (d.recomendaciones.length? '<p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Recomendaciones</p>'+d.recomendaciones.map(t=>'<p class="text-xs text-slate-600"><i class="fas fa-angle-right mr-1"></i>'+escapeHTML(t)+'</p>').join('') : '')
                + '</div>';
        }
        function cotIaRender(s, d, fuente){
            window.cotIaSave = { solicitudId: s ? s.id : null, resultado: d, fuente: fuente, fecha: new Date().toISOString() };
            const host = document.getElementById('cot-ia-vivo');
            const host2 = document.getElementById('cot-ia-bloque-guardado');
            if(host){ host.classList.remove('hidden'); host.innerHTML = '<div id="cot-ia-vivo-inner">'+cotIaHtml(d, fuente)+'</div>'; }
            else if(host2){ host2.innerHTML = '<div id="cot-ia-vivo-inner">'+cotIaHtml(d, fuente)+'</div>'; }
        }
        function cotIaBloqueGuardado(s){
            const ia = s.cotizacion && s.cotizacion.ia;
            if(!ia || !ia.resultado) return '';
            const d = ia.resultado; const dObj = d||{};
            if(!dObj.diferencias) dObj.diferencias = [];
            if(!dObj.datosCorrectos) dObj.datosCorrectos = [];
            if(!dObj.sinInformacion) dObj.sinInformacion = [];
            if(!dObj.recomendaciones) dObj.recomendaciones = [];
            return '<div id="cot-ia-bloque-guardado">'+cotIaHtml(dObj, (ia.fuente||'')+' · '+new Date(ia.fecha).toLocaleString('es-MX'))+'</div>'
                + '<p class="text-[10px] text-slate-400 mb-2"><i class="fas fa-info-circle mr-1"></i>Este análisis se guardó con la cotización. Puedes re-analizar desde la vista en vivo al cargar una nueva versión.</p>'
                + '<div id="cot-ia-vivo" class="hidden"><div id="cot-ia-vivo-inner"></div></div>';
        }
        /* ---------- Historial de revisiones del analista ---------- */
        function cotRevAgregar(s, a){
            if(!a || !a.revision) return;
            if(!Array.isArray(s.revisiones)) s.revisiones = [];
            s.revisiones.unshift({
                fecha: a.revision.fecha || new Date().toISOString(),
                por: a.revision.por,
                score: a.score, aprobado: a.aprobado,
                coincidencias: (a.revision.coincidencias||[]).length,
                diferencias: (a.revision.diferencias||[]).map(x=>x.etiqueta+': póliza "'+x.poliza+'" vs solicitud "'+x.solicitud+'"'),
                sinCotejar: a.revision.sinCotejar||[],
                problemas: a.problemas.map(p=>p.sev+': '+p.tipo+' — '+p.detalle),
                documentos: a.revision.documentos||{},
                version: (s.cotizacion && s.cotizacion.version) || 1,
                prima: s.cotizacion ? s.cotizacion.primaAnual : null
            });
            if(s.revisiones.length>50) s.revisiones.length = 50;
        }
        function cotRevHistorialHtml(s){
            if(!Array.isArray(s.revisiones) || !s.revisiones.length) return '';
            const filas = s.revisiones.map((r,i)=>{
                const c = r.aprobado?'bg-emerald-50 border-emerald-200':(r.score>=50?'bg-amber-50 border-amber-200':'bg-red-50 border-red-200');
                const ic = r.aprobado?'fa-circle-check text-emerald-600':(r.score>=50?'fa-triangle-exclamation text-amber-600':'fa-circle-xmark text-red-500');
                const difs = (r.diferencias||[]).map(d=>'<p class="text-[11px] text-red-700"><i class="fas fa-not-equal mr-1"></i>'+escapeHTML(d)+'</p>').join('');
                const pend = (r.sinCotejar||[]).length? '<p class="text-[11px] text-amber-700"><i class="fas fa-hourglass-half mr-1"></i>Sin cotejar: '+escapeHTML(r.sinCotejar.join(', '))+'</p>' : '';
                const probs = (r.problemas||[]).filter(p=>!/^alta: No coincide/.test(p)).slice(0,4).map(p=>'<p class="text-[11px] text-slate-600"><i class="fas fa-angle-right mr-1"></i>'+escapeHTML(p)+'</p>').join('');
                const docs = (r.documentos&&r.documentos.faltantes&&r.documentos.faltantes.length)? '<p class="text-[11px] text-amber-700"><i class="fas fa-file-circle-exclamation mr-1"></i>Docs faltantes: '+escapeHTML(r.documentos.faltantes.join(', '))+'</p>' : '';
                return '<details class="border rounded-xl px-3 py-2 '+c+'">'
                    + '<summary class="cursor-pointer select-none text-xs font-semibold text-slate-700 flex items-center justify-between gap-2">'
                    + '<span><i class="fas '+ic+' mr-1"></i>Revisión '+(s.revisiones.length-i)+' · v'+r.version+(r.prima?' · $'+Number(r.prima).toLocaleString('es-MX')+' MXN':'')+'</span>'
                    + '<span class="text-[10px] text-slate-500">'+new Date(r.fecha).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+' · '+escapeHTML(r.por&&r.por.nombre?r.por.nombre:'—')+' · score '+r.score+'/100</span></summary>'
                    + '<div class="mt-2 space-y-1">'+difs+pend+docs+probs+'</div></details>';
            }).join('');
            return '<div class="mt-4"><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1"><i class="fas fa-clock-rotate-left mr-1"></i>Historial de revisiones ('+s.revisiones.length+')</p><div class="space-y-2">'+filas+'</div></div>';
        }
        function cotAnalistaBadge(a){
            const nivel = a.aprobado ? ['GO','bg-emerald-100 text-emerald-700 border-emerald-300'] : (a.score>=50 ? ['REVISAR','bg-amber-100 text-amber-700 border-amber-300'] : ['NO GO','bg-red-100 text-red-700 border-red-300']);
            const icon = a.aprobado?'fa-circle-check':(a.score>=50?'fa-triangle-exclamation':'fa-circle-xmark');
            return '<div class="flex items-center justify-between bg-slate-50 rounded-xl border border-slate-200 px-4 py-3 mb-3"><div class="flex items-center gap-3"><div class="w-10 h-10 rounded-xl bg-slate-900 flex items-center justify-center"><i class="fas fa-robot text-emerald-400"></i></div><div><p class="text-xs font-bold uppercase text-slate-500">Analista de cotización</p><p class="text-sm text-slate-700">'+a.problemas.length+' observación'+(a.problemas.length===1?'':'es')+' detectada'+(a.problemas.length===1?'':'s')+'</p></div></div><div class="text-right"><span class="inline-block px-3 py-1 rounded-full text-xs font-bold border '+nivel[1]+'"><i class="fas '+icon+' mr-1"></i>'+nivel[0]+'</span><p class="text-xs text-slate-500 mt-1">Score <b class="text-slate-700">'+a.score+'/100</b></p></div></div>'
                + (a.problemas.length? '<div class="space-y-1.5 mb-3">'+a.problemas.map(p=>{
                    const c = p.sev==='alta'?'bg-red-50 border-red-200 text-red-700':(p.sev==='media'?'bg-amber-50 border-amber-200 text-amber-700':'bg-slate-50 border-slate-200 text-slate-600');
                    const ic = p.sev==='alta'?'fa-circle-exclamation':(p.sev==='media'?'fa-triangle-exclamation':'fa-info-circle');
                    return '<div class="flex items-start gap-2 border rounded-lg px-3 py-2 text-xs '+c+'"><i class="fas '+ic+' mt-0.5"></i><div><b>'+p.tipo+':</b> '+escapeHTML(p.detalle)+'</div></div>';
                  }).join('')+'</div>' : '')
                + ((a.confirmaciones&&a.confirmaciones.length)? '<details class="mb-3 bg-emerald-50 border border-emerald-200 rounded-xl p-3"><summary class="cursor-pointer select-none text-xs font-bold uppercase text-emerald-700"><i class="fas fa-circle-check mr-1"></i>Datos confirmados contra la póliza ('+a.confirmaciones.length+')</summary><div class="space-y-1 mt-2">'+a.confirmaciones.map(t=>'<p class="text-xs text-emerald-800"><i class="fas fa-check text-emerald-500 mr-1"></i>'+escapeHTML(t)+'</p>').join('')+'</div></details>' : '');
        }
        function cotCmpInputs(s){
            const d = s.detalles||{};
            const pares = COT_PARES;
            return pares.filter(k=>{
                const sol = (k==='nombre'||k==='edad') ? cotNormTxt(k==='nombre'?s.cliente.nombre:s.cliente.edad) : cotNormTxt(d[k]);
                return !!sol;
            }).map(k=>{
                const sol = (k==='nombre'||k==='edad') ? (k==='nombre'?s.cliente.nombre:s.cliente.edad) : d[k];
                return '<div><label class="text-[10px] font-semibold text-slate-400 uppercase">'+escapeHTML(cotVerCampo(k))+'</label>'
                    +'<p class="text-xs text-slate-700 bg-slate-100 rounded-lg px-2 py-1.5 truncate" title="Solicitado por el agente">'+escapeHTML(String(sol))+'</p>'
                    +'<input id="cot-cmp-'+k+'" placeholder="Según póliza real…" class="w-full mt-1 px-2 py-1.5 border border-slate-200 rounded-lg text-sm bg-white text-slate-900"><p class="text-[9px] text-slate-400 mt-0.5">'+escapeHTML(cotVerCampo(k))+'</p></div>';
            }).join('');
        }
        function cotReevaluarEnVivo(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            const a = cotAnalista(s);
            const box = document.getElementById('cot-analista-vivo');
            if(box) box.innerHTML = cotAnalistaBadge(a);
        }
        function cotLeerCotejo(){
            const out = {};
            document.querySelectorAll('[id^="cot-cmp-"]').forEach(el=>{
                const k = el.id.replace('cot-cmp-','');
                if(el.value && el.value.trim()) out[k]=el.value.trim();
            });
            return out;
        }
        function cotCotejoPendiente(s){
            const cotejo = (s.cotizacion&&s.cotizacion.cotejo)||{};
            const d = s.detalles||{};
            const pares = COT_PARES;
            return pares.filter(k=>{
                const sol = (k==='nombre'||k==='edad') ? cotNormTxt(k==='nombre'?s.cliente.nombre:s.cliente.edad) : cotNormTxt(d[k]);
                return sol && !cotNormTxt(cotejo[k]);
            });
        }
        /* ---------- Detalle / chat / procesamiento ---------- */
        function cotAbrir(id, tab){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            window.cotModalId = id; window.cotModalTab = tab||'resumen';
            cotMarcarVisto(s); saveDB(); updateBadgeCotizaciones();
            const esProc = cotEsProcesador();
            const esPropio = String(s.creadoPor.id)===String(currentUser.id);
            if(!esProc && !esPropio) return;
            const tabs = [['resumen','Resumen','fa-file-lines'],['chat','Chat ('+(s.chat||[]).length+')','fa-comments'],['cotizacion','Cotización','fa-file-invoice-dollar']];
            const r = cotRamo(s.ramo);
            const chatHtml = (s.chat||[]).map(m=>{
                if(m.sistema) return '<div class="text-center my-2"><span class="text-[11px] text-slate-400 bg-slate-100 rounded-full px-3 py-1"><i class="fas fa-circle-info mr-1"></i>'+escapeHTML(m.texto)+'</span></div>';
                const mio = String(m.de.id)===String(currentUser.id);
                return '<div class="flex '+(mio?'justify-end':'justify-start')+' mb-2"><div class="'+(mio?'bg-emerald-600 text-white':'bg-slate-100 text-slate-700')+' rounded-2xl px-3 py-2 max-w-[75%]"><p class="text-xs font-bold mb-0.5">'+escapeHTML(m.de.nombre)+(m.de.rol?' · '+m.de.rol.replace('_',' '):'')+'</p><p class="text-sm whitespace-pre-wrap">'+escapeHTML(m.texto)+'</p><p class="text-[10px] '+(mio?'text-emerald-200':'text-slate-400')+' mt-1 text-right">'+new Date(m.fecha).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+'</p></div></div>';
            }).join('') || '<p class="text-center text-slate-400 text-sm py-6">Sin mensajes todavía.</p>';
            const checklistHtml = (s.checklist||[]).map(c=>'<label class="flex items-center gap-2 text-sm '+(c.ok?'text-slate-500 line-through':'text-slate-700 font-medium')+'"><i class="fas '+(c.ok?'fa-circle-check text-emerald-500':'fa-circle text-slate-300')+'"></i>'+escapeHTML(c.t)+'</label>').join('');
            const docsHtml = (s.docs||[]).map((d,i)=>'<a href="'+d.dataURL+'" download="'+escapeHTML(d.nombre)+'" class="inline-flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-lg px-3 py-1.5 text-xs font-medium text-slate-600 hover:bg-slate-100"><i class="fas '+(/pdf/.test(d.tipo)?'fa-file-pdf text-red-500':'fa-file-image text-blue-500')+'"></i>'+escapeHTML(d.nombre)+'</a>').join('') || '<p class="text-xs text-slate-400">Sin documentos adjuntos.</p>';
            const detHtml = Object.entries(s.detalles||{}).map(([k,v])=>'<div><p class="text-[10px] uppercase font-semibold text-slate-400">'+escapeHTML(k)+'</p><p class="text-sm text-slate-700">'+escapeHTML(String(v))+'</p></div>').join('');
            let acciones = '';
            if(esProc && ['solicitud','revision','aclaracion'].includes(s.estado)){
                if(!s.asignadoA) acciones += '<button onclick="cotTomar(\''+s.id+'\')" class="px-4 py-2 bg-blue-600 text-white rounded-xl text-sm font-semibold hover:bg-blue-700"><i class="fas fa-hand-paper mr-1"></i> Tomar solicitud</button>';
                else if(String(s.asignadoA.id)===String(currentUser.id)) acciones += '<span class="text-xs bg-blue-50 text-blue-700 px-3 py-2 rounded-xl font-semibold"><i class="fas fa-user-check mr-1"></i>Atendiéndola tú</span>';
                else acciones += '<span class="text-xs bg-slate-100 text-slate-500 px-3 py-2 rounded-xl font-semibold"><i class="fas fa-user mr-1"></i>Asignada a '+escapeHTML(s.asignadoA.nombre)+'</span>';
                acciones += '<button onclick="cotPedirAclaracion(\''+s.id+'\')" class="px-4 py-2 bg-amber-500 text-white rounded-xl text-sm font-semibold hover:bg-amber-600"><i class="fas fa-circle-question mr-1"></i> Pedir aclaración</button>';
                acciones += '<button onclick="cotRechazar(\''+s.id+'\')" class="px-4 py-2 bg-slate-200 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-300"><i class="fas fa-ban mr-1"></i> Rechazar</button>';
            }
            if(esPropio && s.estado==='aclaracion') acciones += '<span class="text-xs bg-orange-100 text-orange-700 px-3 py-2 rounded-xl font-semibold"><i class="fas fa-comment-dots mr-1"></i>Responde en el chat la aclaración solicitada</span>';
            const bodyHtml = {
                resumen: `<div class="space-y-4">
                    ${acciones? '<div class="flex flex-wrap gap-2">'+acciones+'</div>' : ''}
                    <div class="grid sm:grid-cols-2 gap-3 text-sm">
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400">Ramo</p><p>${escapeHTML(s.ramoNombre)}</p></div>
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400">Compañía solicitada</p><p>${escapeHTML(s.compania)}</p></div>
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400">Cliente</p><p>${escapeHTML(s.cliente.nombre)}${s.cliente.edad?' · '+escapeHTML(s.cliente.edad)+' años':''}${s.cliente.persona==='moral'?' · Persona moral':''}</p></div>
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400">Contacto</p><p>${escapeHTML(s.cliente.telefono||'—')} · ${escapeHTML(s.cliente.email||'—')}</p></div>
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400">Solicitó</p><p>${escapeHTML(s.creadoPor.nombre)} · ${new Date(s.creado).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</p></div>
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400">Medidor de respuesta</p><div class="mt-1">${cotBarraSla(s)}</div></div>
                    </div>
                    ${detHtml? '<div><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Especificaciones del ramo</p><div class="grid sm:grid-cols-3 gap-3 bg-slate-50 rounded-xl p-3">'+detHtml+'</div></div>':''}
                    ${s.notas? '<div><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Notas</p><p class="text-sm text-slate-600 bg-amber-50 border border-amber-200 rounded-lg p-2">'+escapeHTML(s.notas)+'</p></div>':''}
                    <div class="grid sm:grid-cols-2 gap-4">
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Checklist de requisitos</p><div class="space-y-1">${checklistHtml}</div></div>
                        <div><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Documentos</p><div class="flex flex-wrap gap-2">${docsHtml}</div></div>
                    </div>
                    <div><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1">Historial</p>
                        <div class="space-y-1">${(s.chat||[]).filter(m=>m.sistema).map(m=>'<p class="text-[11px] text-slate-400"><i class="fas fa-clock mr-1"></i>'+new Date(m.fecha).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})+' — '+escapeHTML(m.texto)+'</p>').join('')}</div></div>
                </div>`,
                chat: `<div id="cot-chat-lista" class="space-y-1 max-h-[46vh] overflow-y-auto pr-1">${chatHtml}</div>
                    <div class="flex gap-2 mt-3"><input id="cot-chat-input" onkeydown="if(event.key==='Enter')cotEnviarMsg('${s.id}')" placeholder="Escribe un mensaje…" class="flex-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"><button onclick="cotEnviarMsg('${s.id}')" class="px-4 py-2 bg-emerald-600 text-white rounded-xl text-sm font-semibold hover:bg-emerald-700"><i class="fas fa-paper-plane"></i></button></div>`,
                cotizacion: cotTabCotizacionHtml(s, esProc, esPropio)
            }[window.cotModalTab] || '';
            showModal(`<div class="max-w-4xl w-full bg-white rounded-2xl modal-scroll" onclick="event.stopPropagation()">
                <div class="p-6 pb-3 border-b border-slate-100">
                    <div class="flex items-start justify-between gap-3">
                        <div><div class="flex items-center gap-2 flex-wrap"><h3 class="text-lg font-bold text-slate-800">${s.id}</h3><span class="px-2 py-0.5 rounded-full text-[10px] font-bold ${COT_ESTADO_COLOR[s.estado]}">${COT_ESTADO_LABEL[s.estado]||s.estado}</span></div>
                        <p class="text-sm text-slate-500 mt-0.5"><i class="fas ${r.icon} text-emerald-600 mr-1"></i>${escapeHTML(s.ramoNombre)} · ${escapeHTML(s.compania)}</p></div>
                        <button onclick="cotCerrarModal()" class="text-slate-400 hover:text-slate-700"><i class="fas fa-times text-lg"></i></button>
                    </div>
                    <div class="flex gap-1 mt-4">${tabs.map(t=>`<button onclick="cotAbrir('${s.id}','${t[0]}')" class="px-3 py-1.5 rounded-lg text-xs font-semibold ${window.cotModalTab===t[0]?'bg-slate-900 text-white':'bg-slate-100 text-slate-600 hover:bg-slate-200'}"><i class="fas ${t[2]} mr-1"></i>${t[1]}</button>`).join('')}</div>
                </div>
                <div class="p-6">${bodyHtml}</div>
            </div>`);
            const lista = document.getElementById('cot-chat-lista');
            if(lista) lista.scrollTop = lista.scrollHeight;
        }
        function cotCerrarModal(){ window.cotModalId=null; closeModal(); }
        function cotTabCotizacionHtml(s, esProc, esPropio){
            const q = s.cotizacion;
            let html = '';
            if(esProc && ['revision','aclaracion','solicitud'].includes(s.estado) && !q){
                html += `<div class="grid lg:grid-cols-2 gap-4 items-start">
                    <div class="bg-slate-50 border border-slate-200 rounded-xl p-4 space-y-3">
                        <p class="text-xs font-bold uppercase text-slate-500"><i class="fas fa-upload text-emerald-600 mr-1"></i> Cargar cotización del analista</p>
                        <div class="grid sm:grid-cols-2 gap-3">
                            <div><label class="text-xs font-semibold text-slate-500">Compañía que cotiza</label><select id="cot-q-comp" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm">${cotCompanias().filter(c=>c!=='Sin preferencia').map(c=>`<option ${c===s.compania?'selected':''}>${c}</option>`).join('')}</select></div>
                            <div><label class="text-xs font-semibold text-slate-500">Asegurado según documento</label><input id="cot-q-aseg" value="${escapeHTML(s.cliente.nombre)}" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"></div>
                            <div><label class="text-xs font-semibold text-slate-500">Prima anual (MXN) *</label><input id="cot-q-prima" type="number" min="0" step="0.01" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="Ej. 18500.00"></div>
                            <div><label class="text-xs font-semibold text-slate-500">Forma de pago</label><select id="cot-q-pago" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"><option>Anual</option><option>Semestral</option><option>Trimestral</option><option>Mensual</option></select></div>
                            <div><label class="text-xs font-semibold text-slate-500">Vigencia de la cotización</label><input id="cot-q-vig" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="Ej. 15 días naturales"></div>
                            <div><label class="text-xs font-semibold text-slate-500">Documento (PDF / imagen) *</label><input id="cot-q-file" type="file" accept="image/*,.pdf" class="w-full mt-1 text-sm border border-slate-200 rounded-xl px-3 py-1.5"></div>
                        </div>
                        <div><label class="text-xs font-semibold text-slate-500">Notas del procesador para el agente</label><textarea id="cot-q-nota" rows="2" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm" placeholder="Deducibles, exclusiones relevantes, condiciones…"></textarea></div>
                        <div class="flex flex-wrap gap-2">
                            <button onclick="cotCargarYAnalizar('${s.id}')" class="px-4 py-2 bg-slate-900 text-white rounded-xl text-sm font-semibold hover:bg-slate-800"><i class="fas fa-robot mr-1"></i> Cargar y analizar</button>
                        </div>
                    </div>
                    <div class="bg-white border-2 border-dashed border-emerald-200 rounded-xl p-4">
                        <p class="text-xs font-bold uppercase text-emerald-700 mb-2"><i class="fas fa-robot text-emerald-600 mr-1"></i> Analista de cotización — vista en vivo</p>
                        <p class="text-[11px] text-slate-400 mb-3">El analista compara cada dato de la solicitud contra la póliza real: escribe lo que dice el documento (o pega su texto) y te marca qué es diferente, qué documentos faltan y qué queda sin cotejar.</p>
                        <div class="mb-3 border-2 border-dashed border-emerald-200 rounded-xl p-3 bg-emerald-50/40">
                            <p class="text-xs font-bold uppercase text-emerald-700 mb-2"><i class="fas fa-wand-magic-sparkles text-emerald-600 mr-1"></i> Análisis con IA del documento</p>
                            <p class="text-[11px] text-slate-500 mb-2">Carga el PDF o imagen de la cotización/póliza y la IA lo analiza a detalle, lo compara con la solicitud (tipo de seguro, asegurado, prima, suma, deducible, coaseguro, gama…) y te informa errores y diferencias.</p>
                            <input id="cot-ia-doc" type="file" accept="application/pdf,image/*" onchange="cotIaDocCargada()" class="w-full text-sm border border-slate-200 rounded-xl px-3 py-1.5 bg-white">
                            <p id="cot-ia-doc-info" class="text-[11px] text-slate-400 mt-1">Opcional: si no cargas documento, la IA analiza el texto pegado abajo (o el PDF adjunto en "Cargar cotización").</p>
                        </div>
                        <div id="cot-ia-vivo" class="hidden mb-3"><div id="cot-ia-vivo-inner"></div></div>
                        <div class="mb-3"><label class="text-[10px] font-semibold text-slate-400 uppercase">Texto de la póliza (opcional, para análisis automático)</label><textarea id="cot-q-poltxt" rows="2" placeholder="Pega aquí el texto de la cotización/póliza: asegurado, prima, deducible, coaseguro, gama, CP…" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-xs font-mono bg-white text-slate-900"></textarea></div>
                        <button onclick="cotIaAnalizar('${s.id}', this)" class="mt-1 px-4 py-2 bg-violet-600 text-white rounded-xl text-sm font-semibold hover:bg-violet-700"><i class="fas fa-wand-magic-sparkles mr-1"></i> Analizar con IA</button>
                        <div class="grid sm:grid-cols-2 gap-2 mb-3">${cotCmpInputs(s)}</div>
                        <div id="cot-analista-vivo">${cotAnalistaBadge(cotAnalista(s))}</div>
                        <button onclick="cotReevaluarEnVivo('${s.id}')" class="mt-2 px-3 py-1.5 border border-slate-300 rounded-lg text-xs font-semibold text-slate-600 hover:bg-slate-50"><i class="fas fa-rotate mr-1"></i> Analizar ahora</button>
                    </div>
                </div>`;
            }
            if(q){
                const a = q.analisis || cotAnalista(s);
                html += cotAnalistaBadge(a);
                if(q.ia && q.ia.resultado) html += cotIaBloqueGuardado(s);
                html += `<div class="grid sm:grid-cols-2 gap-3 text-sm bg-white border border-slate-200 rounded-xl p-4">
                    <div><p class="text-[10px] uppercase font-semibold text-slate-400">Compañía</p><p class="font-semibold">${escapeHTML(q.compania||s.compania)}</p></div>
                    <div><p class="text-[10px] uppercase font-semibold text-slate-400">Prima anual</p><p class="font-bold text-emerald-700">$${Number(q.primaAnual||0).toLocaleString('es-MX',{minimumFractionDigits:2})} MXN</p></div>
                    <div><p class="text-[10px] uppercase font-semibold text-slate-400">Forma de pago</p><p>${escapeHTML(q.formaPago||'—')}</p></div>
                    <div><p class="text-[10px] uppercase font-semibold text-slate-400">Vigencia</p><p>${escapeHTML(q.vigencia||'—')}</p></div>
                    ${q.notas? '<div class="sm:col-span-2"><p class="text-[10px] uppercase font-semibold text-slate-400">Notas del procesador</p><p class="text-slate-600">'+escapeHTML(q.notas)+'</p></div>':''}
                    <div class="sm:col-span-2">${q.archivo&&q.archivo.dataURL? '<a href="'+q.archivo.dataURL+'" download="'+escapeHTML(q.archivo.nombre||'cotizacion.pdf')+'" class="inline-flex items-center gap-2 bg-slate-900 text-white rounded-xl px-4 py-2 text-xs font-semibold hover:bg-slate-800"><i class="fas fa-file-download"></i> Descargar documento de cotización</a>' : '<p class="text-xs text-red-500"><i class="fas fa-triangle-exclamation mr-1"></i>Sin documento adjunto.</p>'}</div>
                </div>`;
                if(q.cotejo && Object.keys(q.cotejo).length){
                    html += `<div class="mt-3"><p class="text-[10px] uppercase font-semibold text-slate-400 mb-1"><i class="fas fa-table-columns mr-1"></i>Cotejo póliza vs solicitud</p><div class="overflow-x-auto border border-slate-200 rounded-xl"><table class="w-full text-xs">
                        <thead class="bg-slate-50"><tr><th class="text-left px-2 py-1.5 text-slate-500 uppercase font-semibold">Campo</th><th class="text-left px-2 py-1.5 text-slate-500 uppercase font-semibold">Solicitud</th><th class="text-left px-2 py-1.5 text-slate-500 uppercase font-semibold">Póliza</th><th class="px-2 py-1.5"></th></tr></thead>
                        <tbody class="divide-y divide-slate-100">${Object.entries(q.cotejo).map(([k,pol])=>{ const sol = (k==='nombre'||k==='edad')? (k==='nombre'?s.cliente.nombre:s.cliente.edad) : ((s.detalles||{})[k]); const same = cotNormTxt(sol).toUpperCase()===cotNormTxt(pol).toUpperCase(); return '<tr><td class="px-2 py-1.5 font-semibold text-slate-600">'+escapeHTML(cotVerCampo(k))+'</td><td class="px-2 py-1.5 text-slate-700">'+escapeHTML(String(sol==null||sol===''?'—':sol))+'</td><td class="px-2 py-1.5 text-slate-700">'+escapeHTML(String(pol))+'</td><td class="px-2 py-1.5 text-center">'+(same?'<i class="fas fa-circle-check text-emerald-500"></i>':'<i class="fas fa-circle-xmark text-red-500"></i>')+'</td></tr>'; }).join('')}</tbody>
                    </table></div></div>`;
                }
                if(esProc && ['revision','aclaracion','solicitud'].includes(s.estado)){
                    html += `<details class="bg-white border border-slate-200 rounded-xl p-4"><summary class="cursor-pointer select-none text-xs font-bold uppercase text-slate-500"><i class="fas fa-rotate text-emerald-600 mr-1"></i>Cargar nueva versión (corrección)</summary><div class="mt-3 space-y-3">
                        <div class="grid sm:grid-cols-2 gap-3">
                            <div><label class="text-xs font-semibold text-slate-500">Compañía que cotiza</label><select id="cot-r-comp" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm">${cotCompanias().filter(c=>c!=='Sin preferencia').map(c=>`<option ${c===q.compania?'selected':''}>${c}</option>`).join('')}</select></div>
                            <div><label class="text-xs font-semibold text-slate-500">Asegurado según documento</label><input id="cot-r-aseg" value="${escapeHTML(q.asegurado||s.cliente.nombre)}" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"></div>
                            <div><label class="text-xs font-semibold text-slate-500">Prima anual (MXN) *</label><input id="cot-r-prima" type="number" min="0" step="0.01" value="${Number(q.primaAnual||0)||''}" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"></div>
                            <div><label class="text-xs font-semibold text-slate-500">Forma de pago</label><select id="cot-r-pago" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm">${['Anual','Semestral','Trimestral','Mensual'].map(p=>`<option ${p===(q.formaPago||'Anual')?'selected':''}>${p}</option>`).join('')}</select></div>
                            <div><label class="text-xs font-semibold text-slate-500">Vigencia de la cotización</label><input id="cot-r-vig" value="${escapeHTML(q.vigencia||'')}" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm"></div>
                            <div><label class="text-xs font-semibold text-slate-500">Nuevo documento (opcional)</label><input id="cot-r-file" type="file" accept="image/*,.pdf" class="w-full mt-1 text-sm border border-slate-200 rounded-xl px-3 py-1.5"></div>
                            <div class="sm:col-span-2">
                                <div class="border-2 border-dashed border-emerald-200 rounded-xl p-3 bg-emerald-50/40 mb-2">
                                    <p class="text-xs font-bold uppercase text-emerald-700 mb-2"><i class="fas fa-wand-magic-sparkles text-emerald-600 mr-1"></i> Análisis con IA del documento (nueva versión)</p>
                                    <input id="cot-ia-doc-r" type="file" accept="application/pdf,image/*" onchange="cotIaDocCargada()" class="w-full text-sm border border-slate-200 rounded-xl px-3 py-1.5 bg-white">
                                    <p id="cot-ia-doc-info" class="text-[11px] text-slate-400 mt-1">Opcional: analiza el texto pegado abajo o el PDF adjunto.</p>
                                </div>
                                <label class="text-xs font-semibold text-slate-500">Texto de la póliza (opcional, para análisis automático)</label><textarea id="cot-r-poltxt" rows="2" placeholder="Pega el texto de la nueva versión de la póliza…" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-xs font-mono bg-white text-slate-900"></textarea>
                                <button onclick="cotIaAnalizar('${s.id}', this)" class="mt-2 px-4 py-2 bg-violet-600 text-white rounded-xl text-sm font-semibold hover:bg-violet-700"><i class="fas fa-wand-magic-sparkles mr-1"></i> Analizar con IA</button>
                            </div>
                        </div>
                        <div><label class="text-xs font-semibold text-slate-500">Notas del procesador para el agente</label><textarea id="cot-r-nota" rows="2" class="w-full mt-1 px-3 py-2 border border-slate-200 rounded-xl text-sm">${escapeHTML(q.notas||'')}</textarea></div>
                        <div><button onclick="cotRecargar('${s.id}')" class="px-4 py-2 bg-slate-900 text-white rounded-xl text-sm font-semibold hover:bg-slate-800"><i class="fas fa-robot mr-1"></i> Re-analizar versión corregida</button></div>
                    </div></details>`;
                }
                html += cotRevHistorialHtml(s);
            if(esProc && s.estado==='revision'){
                const pend = cotCotejoPendiente(s);
                html += `<div class="flex flex-wrap gap-2 mt-4">`
                    + (pend.length? `<span class="text-xs bg-amber-50 text-amber-700 border border-amber-200 px-3 py-2 rounded-xl font-semibold"><i class="fas fa-triangle-exclamation mr-1"></i>${pend.length} dato(s) sin cotejar con la póliza</span>` : `<span class="text-xs bg-emerald-50 text-emerald-700 border border-emerald-200 px-3 py-2 rounded-xl font-semibold"><i class="fas fa-circle-check mr-1"></i>Cotejo póliza↔solicitud completo</span>`)
                    + `<button onclick="cotEnviarAgente('${s.id}')" class="px-4 py-2 bg-emerald-600 text-white rounded-xl text-sm font-semibold hover:bg-emerald-700"><i class="fas fa-paper-plane mr-1"></i> Enviar al agente</button></div>`;
            }
            }
            if(esPropio && s.estado==='cotizada'){
                html += `<div class="bg-violet-50 border border-violet-200 rounded-xl p-4 mt-4"><p class="text-sm font-bold text-violet-800 mb-2"><i class="fas fa-flag-checkered mr-1"></i> ¿Cómo deseas proceder con esta cotización?</p>
                    <div class="flex flex-wrap gap-2">
                        <button onclick="cotDecidir('${s.id}','emitir')" class="px-4 py-2 bg-emerald-600 text-white rounded-xl text-sm font-semibold hover:bg-emerald-700"><i class="fas fa-check mr-1"></i> Emitir póliza</button>
                        <button onclick="cotDecidir('${s.id}','no-emitir')" class="px-4 py-2 bg-slate-300 text-slate-700 rounded-xl text-sm font-semibold hover:bg-slate-400"><i class="fas fa-times mr-1"></i> No emitir</button>
                    </div></div>`;
            }
            if(!q && !esProc) html += '<p class="text-center text-slate-400 text-sm py-8"><i class="fas fa-hourglass-half text-2xl block mb-2"></i>Aún no hay cotización cargada. Te avisaremos en el chat cuando esté lista.</p>';
            if(!q && esProc && !['revision','aclaracion','solicitud'].includes(s.estado)) html += '<p class="text-center text-slate-400 text-sm py-8">Sin cotización en esta etapa.</p>';
            return html;
        }
        function cotTomar(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            s.asignadoA = {id:currentUser.id, nombre:currentUser.name||currentUser.username};
            s.estado = 'revision'; s.estadoDesde = new Date().toISOString();
            s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:'Tomada por '+(currentUser.name||currentUser.username)+'. En revisión.', fecha:Date.now(), sistema:true});
            saveDB(); showToast('Solicitud '+s.id+' asignada a ti', 'success'); cotAbrir(id,'resumen'); updateBadgeCotizaciones();
        }
        function cotPedirAclaracion(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            const nota = prompt('¿Qué debe aclarar o corregir el agente?');
            if(!nota) return;
            s.estado = 'aclaracion'; s.estadoDesde = new Date().toISOString();
            s.chat.push({de:{id:currentUser.id, nombre:currentUser.name||currentUser.username, rol:currentUser.role}, texto:'⚠️ Aclaración requerida: '+nota, fecha:Date.now()});
            saveDB(); showToast('Aclaración pedida al agente', 'info'); cotAbrir(id,'chat');
        }
        function cotRechazar(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            const nota = prompt('Motivo del rechazo:');
            if(!nota) return;
            s.estado = 'rechazada'; s.estadoDesde = new Date().toISOString();
            s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:'Solicitud rechazada por '+(currentUser.name||currentUser.username)+'. Motivo: '+nota, fecha:Date.now(), sistema:true});
            saveDB(); cotCerrarModal(); showToast('Solicitud '+s.id+' rechazada', 'info'); render();
        }
        function cotEnviarMsg(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            const inp = document.getElementById('cot-chat-input');
            if(!inp || !inp.value.trim()) return;
            s.chat.push({de:{id:currentUser.id, nombre:currentUser.name||currentUser.username, rol:currentUser.role}, texto:inp.value.trim(), fecha:Date.now()});
            saveDB(); cotAbrir(id,'chat'); updateBadgeCotizaciones();
        }
        function cotLeerArchivo(input, cb){
            const f = input && input.files && input.files[0];
            if(!f) return cb(null);
            if(f.size > 2*1024*1024){ showToast('El archivo supera 2 MB', 'error'); return cb(null); }
            const rd = new FileReader();
            rd.onload = e => cb({nombre:f.name, tipo:f.type||'application/pdf', dataURL:e.target.result});
            rd.onerror = () => cb(null);
            rd.readAsDataURL(f);
        }
        function cotCargarYAnalizar(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            const prima = parseFloat(document.getElementById('cot-q-prima').value);
            if(!prima || prima<=0){ showToast('Captura la prima anual', 'error'); return; }
            const inp = document.getElementById('cot-q-file');
            if(!inp.files || !inp.files.length){ showToast('Adjunta el documento de la cotización', 'error'); return; }
            cotLeerArchivo(inp, arch=>{
                if(!arch) return;
                s.cotizacion = {
                    compania: document.getElementById('cot-q-comp').value,
                    asegurado: document.getElementById('cot-q-aseg').value.trim(),
                    primaAnual: prima,
                    formaPago: document.getElementById('cot-q-pago').value,
                    vigencia: document.getElementById('cot-q-vig').value.trim(),
                    notas: document.getElementById('cot-q-nota').value.trim(),
                    archivo: arch,
                    cotejo: cotLeerCotejo(),
                    polizaTexto: (document.getElementById('cot-q-poltxt')||{}).value||'',
                    ia: (window.cotIaSave && window.cotIaSave.solicitudId===id) ? {resultado:window.cotIaSave.resultado, fuente:window.cotIaSave.fuente, fecha:window.cotIaSave.fecha} : null,
                    cargadaEn: new Date().toISOString()
                };
                s.cotizacion.analisis = cotAnalista(s);
                cotRevAgregar(s, s.cotizacion.analisis);
                s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:'Cotización cargada y analizada por '+ (currentUser.name||currentUser.username) +'. Resultado: '+(s.cotizacion.analisis.aprobado?'APROBADA':'REQUIERE REVISIÓN')+' (score '+s.cotizacion.analisis.score+'/100, '+s.cotizacion.analisis.problemas.length+' observaciones).', fecha:Date.now(), sistema:true});
                saveDB(); cotAbrir(id,'cotizacion');
                if(!s.cotizacion.analisis.aprobado) showToast('El analista detectó observaciones: revísalas antes de enviar', 'warning');
            });
        }
        function cotRecargar(id){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            if(!s.cotizacion) return;
            const prima = parseFloat(document.getElementById('cot-r-prima').value);
            if(!prima || prima<=0){ showToast('Captura la prima anual', 'error'); return; }
            const inp = document.getElementById('cot-r-file');
            const aplicar = (arch) => {
                const prevDoc = s.cotizacion.archivo || null; const prevTexto = s.cotizacion.polizaTexto || '';
                s.cotizacion = {
                    compania: document.getElementById('cot-r-comp').value,
                    asegurado: document.getElementById('cot-r-aseg').value.trim(),
                    primaAnual: prima,
                    formaPago: document.getElementById('cot-r-pago').value,
                    vigencia: document.getElementById('cot-r-vig').value.trim(),
                    notas: document.getElementById('cot-r-nota').value.trim(),
                    archivo: arch || prevDoc,
                    cotejo: cotLeerCotejo(),
                    polizaTexto: ((document.getElementById('cot-r-poltxt')||{}).value||'').trim() || prevTexto,
                    ia: (window.cotIaSave && window.cotIaSave.solicitudId===id) ? {resultado:window.cotIaSave.resultado, fuente:window.cotIaSave.fuente, fecha:window.cotIaSave.fecha} : (s.cotizacion.ia||null),
                    cargadaEn: new Date().toISOString(),
                    version: ((s.cotizacion.version||1)+1)
                };
                s.cotizacion.analisis = cotAnalista(s);
                cotRevAgregar(s, s.cotizacion.analisis);
                s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:'Nueva versión de la cotización cargada por '+(currentUser.name||currentUser.username)+'. Resultado: '+(s.cotizacion.analisis.aprobado?'APROBADA':'REQUIERE REVISIÓN')+' (score '+s.cotizacion.analisis.score+'/100, '+s.cotizacion.analisis.problemas.length+' observación(es)).', fecha:Date.now(), sistema:true});
                saveDB(); cotAbrir(id,'cotizacion'); updateBadgeCotizaciones();
                showToast('Versión '+(s.cotizacion.version)+' re-analizada: score '+s.cotizacion.analisis.score+'/100', s.cotizacion.analisis.aprobado?'success':'warning');
            };
            cotLeerArchivo(inp, a => aplicar(a));
        }
        function cotEnviarAgente(id){
            const s = cotDB().find(x=>x.id===id); if(!s || !s.cotizacion) return;
            const a = s.cotizacion.analisis || cotAnalista(s);
            if(!a.aprobado && !confirm('El analista reporta '+a.problemas.length+' observación(es) (score '+a.score+'/100). ¿Enviar de todas formas al agente?')) return;
            s.cotizacion.enviadaEn = new Date().toISOString();
            s.estado = 'cotizada'; s.estadoDesde = new Date().toISOString();
            s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:'Cotización enviada al agente '+s.creadoPor.nombre+'. Prima anual: $'+Number(s.cotizacion.primaAnual).toLocaleString('es-MX')+' MXN ('+s.cotizacion.compania+').', fecha:Date.now(), sistema:true});
            try{ if(Array.isArray(db.notifications)) db.notifications.unshift({id:'notif-cot-'+Date.now(), userId:s.creadoPor.id, type:'cotizacion', mensaje:'Tu cotización '+s.id+' está lista ('+s.cotizacion.compania+')', fecha:new Date().toISOString(), read:false}); }catch(e){}
            saveDB(); showToast('Cotización enviada a '+s.creadoPor.nombre, 'success'); cotAbrir(id,'cotizacion'); updateBadgeCotizaciones();
        }
        function cotDecidir(id, tipo){
            const s = cotDB().find(x=>x.id===id); if(!s) return;
            let nota = '';
            if(tipo==='no-emitir'){ nota = prompt('Comentario (opcional):') || ''; s.estado='cancelada'; }
            else { nota = prompt('Notas de emisión (número de póliza, etc., opcional):') || ''; s.estado='emitida'; }
            s.decision = {tipo, nota, fecha:new Date().toISOString(), por:{id:currentUser.id, nombre:currentUser.name||currentUser.username}};
            s.estadoDesde = new Date().toISOString();
            s.chat.push({de:{id:currentUser.id, nombre:'Sistema', rol:'sistema'}, texto:(tipo==='emitir'?'✔ El agente decidió EMITIR la póliza.':'✖ El agente decidió no emitir.')+(nota?' Nota: '+nota:''), fecha:Date.now(), sistema:true});
            try{ if(Array.isArray(db.notifications)){ const destinos=[]; const addDest=(u)=>{ if(u && u.id!==undefined && String(u.id)!==String(currentUser.id) && !destinos.some(d=>String(d)===String(u.id))) destinos.push(u.id); }; addDest(s.creadoPor); addDest(s.asignadoA); destinos.forEach(uid=>db.notifications.unshift({id:'notif-cotd-'+Date.now()+'-'+uid, userId:uid, type:'cotizacion', mensaje:(tipo==='emitir'?'✔ Póliza EMITIDA en ':'Decisión registrada en ')+s.id, fecha:new Date().toISOString(), read:false})); } }catch(e){}
            saveDB(); cotCerrarModal(); showToast(tipo==='emitir'?'Marcada como emitida. ¡Éxito!':'Solicitud cerrada.', tipo==='emitir'?'success':'info'); render();
        }
function comparadorPuedeEditar(){ return ['admin','gm','editor','capacitador','desarrollador'].includes((currentUser.role||'').toLowerCase()); }
