                                    <tr class="bg-slate-100 border-t border-slate-200">
                                        <td colspan="${roles.length+1}" class="px-4 py-2 font-bold text-slate-700 uppercase text-[11px] tracking-wide"><i class="fas ${cat.icon} mr-2 text-slate-500"></i>${cat.titulo} <span class="text-slate-400 font-normal normal-case">(${cat.secciones.length})</span></td>
                                    </tr>
